     1→package checkpoint
     2→
     3→import (
     4→	"context"
     5→	"crypto/sha256"
     6→	"encoding/json"
     7→	"errors"
     8→	"fmt"
     9→	"log/slog"
    10→	"os"
    11→	"path/filepath"
    12→	"sort"
    13→	"strconv"
    14→	"strings"
    15→	"time"
    16→
    17→	"entire.io/cli/cmd/entire/cli/agent"
    18→	"entire.io/cli/cmd/entire/cli/checkpoint/id"
    19→	"entire.io/cli/cmd/entire/cli/jsonutil"
    20→	"entire.io/cli/cmd/entire/cli/logging"
    21→	"entire.io/cli/cmd/entire/cli/paths"
    22→	"entire.io/cli/cmd/entire/cli/trailers"
    23→	"entire.io/cli/cmd/entire/cli/validation"
    24→
    25→	"github.com/go-git/go-git/v5"
    26→	"github.com/go-git/go-git/v5/plumbing"
    27→	"github.com/go-git/go-git/v5/plumbing/filemode"
    28→	"github.com/go-git/go-git/v5/plumbing/object"
    29→)
    30→
    31→// WriteCommitted writes a committed checkpoint to the entire/sessions branch.
    32→// Checkpoints are stored at sharded paths: <id[:2]>/<id[2:]>/
    33→//
    34→// For task checkpoints (IsTask=true), additional files are written under tasks/<tool-use-id>/:
    35→//   - For incremental checkpoints: checkpoints/NNN-<tool-use-id>.json
    36→//   - For final checkpoints: checkpoint.json and agent-<agent-id>.jsonl
    37→func (s *GitStore) WriteCommitted(ctx context.Context, opts WriteCommittedOptions) error {
    38→	_ = ctx // Reserved for future use
    39→
    40→	// Validate identifiers to prevent path traversal and malformed data
    41→	if opts.CheckpointID.IsEmpty() {
    42→		return errors.New("invalid checkpoint options: checkpoint ID is required")
    43→	}
    44→	if err := validation.ValidateSessionID(opts.SessionID); err != nil {
    45→		return fmt.Errorf("invalid checkpoint options: %w", err)
    46→	}
    47→	if err := validation.ValidateToolUseID(opts.ToolUseID); err != nil {
    48→		return fmt.Errorf("invalid checkpoint options: %w", err)
    49→	}
    50→	if err := validation.ValidateAgentID(opts.AgentID); err != nil {
    51→		return fmt.Errorf("invalid checkpoint options: %w", err)
    52→	}
    53→
    54→	// Ensure sessions branch exists
    55→	if err := s.ensureSessionsBranch(); err != nil {
    56→		return fmt.Errorf("failed to ensure sessions branch: %w", err)
    57→	}
    58→
    59→	// Get current branch tip and flatten tree
    60→	ref, entries, err := s.getSessionsBranchEntries()
    61→	if err != nil {
    62→		return err
    63→	}
    64→
    65→	// Use sharded path: <id[:2]>/<id[2:]>/
    66→	basePath := opts.CheckpointID.Path() + "/"
    67→
    68→	// Track task metadata path for commit trailer
    69→	var taskMetadataPath string
    70→
    71→	// Handle task checkpoints
    72→	if opts.IsTask && opts.ToolUseID != "" {
    73→		taskMetadataPath, err = s.writeTaskCheckpointEntries(opts, basePath, entries)
    74→		if err != nil {
    75→			return err
    76→		}
    77→	}
    78→
    79→	// Write standard checkpoint entries (transcript, prompts, context, metadata)
    80→	if err := s.writeStandardCheckpointEntries(opts, basePath, entries); err != nil {
    81→		return err
    82→	}
    83→
    84→	// Build and commit
    85→	newTreeHash, err := BuildTreeFromEntries(s.repo, entries)
    86→	if err != nil {
    87→		return err
    88→	}
    89→
    90→	commitMsg := s.buildCommitMessage(opts, taskMetadataPath)
    91→	newCommitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, opts.AuthorName, opts.AuthorEmail)
    92→	if err != nil {
    93→		return err
    94→	}
    95→
    96→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
    97→	newRef := plumbing.NewHashReference(refName, newCommitHash)
    98→	if err := s.repo.Storer.SetReference(newRef); err != nil {
    99→		return fmt.Errorf("failed to set branch reference: %w", err)
   100→	}
   101→
   102→	return nil
   103→}
   104→
   105→// getSessionsBranchEntries returns the sessions branch reference and flattened tree entries.
   106→func (s *GitStore) getSessionsBranchEntries() (*plumbing.Reference, map[string]object.TreeEntry, error) {
   107→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   108→	ref, err := s.repo.Reference(refName, true)
   109→	if err != nil {
   110→		return nil, nil, fmt.Errorf("failed to get sessions branch reference: %w", err)
   111→	}
   112→
   113→	parentCommit, err := s.repo.CommitObject(ref.Hash())
   114→	if err != nil {
   115→		return nil, nil, fmt.Errorf("failed to get commit object: %w", err)
   116→	}
   117→
   118→	baseTree, err := parentCommit.Tree()
   119→	if err != nil {
   120→		return nil, nil, fmt.Errorf("failed to get commit tree: %w", err)
   121→	}
   122→
   123→	entries := make(map[string]object.TreeEntry)
   124→	if err := FlattenTree(s.repo, baseTree, "", entries); err != nil {
   125→		return nil, nil, err
   126→	}
   127→
   128→	return ref, entries, nil
   129→}
   130→
   131→// writeTaskCheckpointEntries writes task-specific checkpoint entries and returns the task metadata path.
   132→func (s *GitStore) writeTaskCheckpointEntries(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) (string, error) {
   133→	taskPath := basePath + "tasks/" + opts.ToolUseID + "/"
   134→
   135→	if opts.IsIncremental {
   136→		return s.writeIncrementalTaskCheckpoint(opts, taskPath, entries)
   137→	}
   138→	return s.writeFinalTaskCheckpoint(opts, taskPath, entries)
   139→}
   140→
   141→// writeIncrementalTaskCheckpoint writes an incremental checkpoint file during task execution.
   142→func (s *GitStore) writeIncrementalTaskCheckpoint(opts WriteCommittedOptions, taskPath string, entries map[string]object.TreeEntry) (string, error) {
   143→	checkpoint := incrementalCheckpointData{
   144→		Type:      opts.IncrementalType,
   145→		ToolUseID: opts.ToolUseID,
   146→		Timestamp: time.Now().UTC(),
   147→		Data:      opts.IncrementalData,
   148→	}
   149→	cpData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
   150→	if err != nil {
   151→		return "", fmt.Errorf("failed to marshal incremental checkpoint: %w", err)
   152→	}
   153→	cpBlobHash, err := CreateBlobFromContent(s.repo, cpData)
   154→	if err != nil {
   155→		return "", fmt.Errorf("failed to create incremental checkpoint blob: %w", err)
   156→	}
   157→
   158→	cpFilename := fmt.Sprintf("%03d-%s.json", opts.IncrementalSequence, opts.ToolUseID)
   159→	cpPath := taskPath + "checkpoints/" + cpFilename
   160→	entries[cpPath] = object.TreeEntry{
   161→		Name: cpPath,
   162→		Mode: filemode.Regular,
   163→		Hash: cpBlobHash,
   164→	}
   165→	return cpPath, nil
   166→}
   167→
   168→// writeFinalTaskCheckpoint writes the final checkpoint.json and subagent transcript.
   169→func (s *GitStore) writeFinalTaskCheckpoint(opts WriteCommittedOptions, taskPath string, entries map[string]object.TreeEntry) (string, error) {
   170→	checkpoint := taskCheckpointData{
   171→		SessionID:      opts.SessionID,
   172→		ToolUseID:      opts.ToolUseID,
   173→		CheckpointUUID: opts.CheckpointUUID,
   174→		AgentID:        opts.AgentID,
   175→	}
   176→	checkpointData, err := jsonutil.MarshalIndentWithNewline(checkpoint, "", "  ")
   177→	if err != nil {
   178→		return "", fmt.Errorf("failed to marshal task checkpoint: %w", err)
   179→	}
   180→	blobHash, err := CreateBlobFromContent(s.repo, checkpointData)
   181→	if err != nil {
   182→		return "", fmt.Errorf("failed to create task checkpoint blob: %w", err)
   183→	}
   184→
   185→	checkpointFile := taskPath + "checkpoint.json"
   186→	entries[checkpointFile] = object.TreeEntry{
   187→		Name: checkpointFile,
   188→		Mode: filemode.Regular,
   189→		Hash: blobHash,
   190→	}
   191→
   192→	// Write subagent transcript if available
   193→	if opts.SubagentTranscriptPath != "" && opts.AgentID != "" {
   194→		agentContent, readErr := os.ReadFile(opts.SubagentTranscriptPath)
   195→		if readErr == nil {
   196→			agentBlobHash, agentBlobErr := CreateBlobFromContent(s.repo, agentContent)
   197→			if agentBlobErr == nil {
   198→				agentPath := taskPath + "agent-" + opts.AgentID + ".jsonl"
   199→				entries[agentPath] = object.TreeEntry{
   200→					Name: agentPath,
   201→					Mode: filemode.Regular,
   202→					Hash: agentBlobHash,
   203→				}
   204→			}
   205→		}
   206→	}
   207→
   208→	// Return task path without trailing slash
   209→	return taskPath[:len(taskPath)-1], nil
   210→}
   211→
   212→// writeStandardCheckpointEntries writes transcript, prompts, context, metadata.json and any additional files.
   213→// If the checkpoint already exists (from a previous session), archives the existing files to a numbered subfolder.
   214→func (s *GitStore) writeStandardCheckpointEntries(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
   215→	// Check if checkpoint already exists (multi-session support)
   216→	var existingMetadata *CommittedMetadata
   217→	metadataPath := basePath + paths.MetadataFileName
   218→	if entry, exists := entries[metadataPath]; exists {
   219→		// Read existing metadata to get session count
   220→		existing, err := s.readMetadataFromBlob(entry.Hash)
   221→		if err == nil {
   222→			existingMetadata = existing
   223→			// Archive existing session files to numbered subfolder
   224→			s.archiveExistingSession(basePath, existingMetadata, entries)
   225→		}
   226→	}
   227→
   228→	// Write transcript (from in-memory content or file path)
   229→	if err := s.writeTranscript(opts, basePath, entries); err != nil {
   230→		return err
   231→	}
   232→
   233→	// Write prompts
   234→	if len(opts.Prompts) > 0 {
   235→		promptContent := strings.Join(opts.Prompts, "\n\n---\n\n")
   236→		blobHash, err := CreateBlobFromContent(s.repo, []byte(promptContent))
   237→		if err != nil {
   238→			return err
   239→		}
   240→		entries[basePath+paths.PromptFileName] = object.TreeEntry{
   241→			Name: basePath + paths.PromptFileName,
   242→			Mode: filemode.Regular,
   243→			Hash: blobHash,
   244→		}
   245→	}
   246→
   247→	// Write context
   248→	if len(opts.Context) > 0 {
   249→		blobHash, err := CreateBlobFromContent(s.repo, opts.Context)
   250→		if err != nil {
   251→			return err
   252→		}
   253→		entries[basePath+paths.ContextFileName] = object.TreeEntry{
   254→			Name: basePath + paths.ContextFileName,
   255→			Mode: filemode.Regular,
   256→			Hash: blobHash,
   257→		}
   258→	}
   259→
   260→	// Copy additional metadata files from directory if specified
   261→	if opts.MetadataDir != "" {
   262→		if err := s.copyMetadataDir(opts.MetadataDir, basePath, entries); err != nil {
   263→			return fmt.Errorf("failed to copy metadata directory: %w", err)
   264→		}
   265→	}
   266→
   267→	// Write metadata.json (with merged info if existing metadata present)
   268→	return s.writeMetadataJSON(opts, basePath, entries, existingMetadata)
   269→}
   270→
   271→// writeTranscript writes the transcript file from in-memory content or file path.
   272→// If the transcript exceeds MaxChunkSize, it's split into multiple chunk files.
   273→func (s *GitStore) writeTranscript(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry) error {
   274→	transcript := opts.Transcript
   275→	if len(transcript) == 0 && opts.TranscriptPath != "" {
   276→		var readErr error
   277→		transcript, readErr = os.ReadFile(opts.TranscriptPath)
   278→		if readErr != nil {
   279→			// Non-fatal: transcript may not exist yet
   280→			transcript = nil
   281→		}
   282→	}
   283→	if len(transcript) == 0 {
   284→		return nil
   285→	}
   286→
   287→	// Chunk the transcript if it's too large
   288→	chunks, err := agent.ChunkTranscript(transcript, opts.Agent)
   289→	if err != nil {
   290→		return fmt.Errorf("failed to chunk transcript: %w", err)
   291→	}
   292→
   293→	// Write chunk files
   294→	for i, chunk := range chunks {
   295→		chunkPath := basePath + agent.ChunkFileName(paths.TranscriptFileName, i)
   296→		blobHash, err := CreateBlobFromContent(s.repo, chunk)
   297→		if err != nil {
   298→			return err
   299→		}
   300→		entries[chunkPath] = object.TreeEntry{
   301→			Name: chunkPath,
   302→			Mode: filemode.Regular,
   303→			Hash: blobHash,
   304→		}
   305→	}
   306→
   307→	// Content hash for deduplication (hash of full transcript)
   308→	contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
   309→	hashBlob, err := CreateBlobFromContent(s.repo, []byte(contentHash))
   310→	if err != nil {
   311→		return err
   312→	}
   313→	entries[basePath+paths.ContentHashFileName] = object.TreeEntry{
   314→		Name: basePath + paths.ContentHashFileName,
   315→		Mode: filemode.Regular,
   316→		Hash: hashBlob,
   317→	}
   318→	return nil
   319→}
