   616→// ReadCommitted reads a committed checkpoint by ID from the entire/sessions branch.
   617→// Returns nil, nil if the checkpoint doesn't exist.
   618→//
   619→
   620→func (s *GitStore) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*ReadCommittedResult, error) {
   621→	_ = ctx // Reserved for future use
   622→
   623→	tree, err := s.getSessionsBranchTree()
   624→	if err != nil {
   625→		return nil, nil //nolint:nilnil,nilerr // No sessions branch means no checkpoint exists
   626→	}
   627→
   628→	checkpointPath := checkpointID.Path()
   629→	checkpointTree, err := tree.Tree(checkpointPath)
   630→	if err != nil {
   631→		return nil, nil //nolint:nilnil,nilerr // Checkpoint directory not found
   632→	}
   633→
   634→	result := &ReadCommittedResult{}
   635→
   636→	// Read metadata.json
   637→	if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   638→		if content, contentErr := metadataFile.Contents(); contentErr == nil {
   639→			//nolint:errcheck,gosec // Best-effort parsing, defaults are fine
   640→			json.Unmarshal([]byte(content), &result.Metadata)
   641→		}
   642→	}
   643→
   644→	// Read transcript (handles both chunked and non-chunked formats)
   645→	if transcript, err := readTranscriptFromTree(checkpointTree, result.Metadata.Agent); err == nil && transcript != nil {
   646→		result.Transcript = transcript
   647→	}
   648→
   649→	// Read prompts
   650→	if file, fileErr := checkpointTree.File(paths.PromptFileName); fileErr == nil {
   651→		if content, contentErr := file.Contents(); contentErr == nil {
   652→			result.Prompts = content
   653→		}
   654→	}
   655→
   656→	// Read context
   657→	if file, fileErr := checkpointTree.File(paths.ContextFileName); fileErr == nil {
   658→		if content, contentErr := file.Contents(); contentErr == nil {
   659→			result.Context = content
   660→		}
   661→	}
   662→
   663→	// Read archived sessions if this is a multi-session checkpoint
   664→	if result.Metadata.SessionCount > 1 {
   665→		result.ArchivedSessions = s.readArchivedSessions(checkpointTree, result.Metadata.SessionCount, result.Metadata.Agent)
   666→	}
   667→
   668→	return result, nil
   669→}
   670→
   671→// ListCommitted lists all committed checkpoints from the entire/sessions branch.
   672→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
   673→//
   674→
   675→func (s *GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
   676→	_ = ctx // Reserved for future use
   677→
   678→	tree, err := s.getSessionsBranchTree()
   679→	if err != nil {
   680→		return []CommittedInfo{}, nil //nolint:nilerr // No sessions branch means empty list
   681→	}
   682→
   683→	var checkpoints []CommittedInfo
   684→
   685→	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
   686→	for _, bucketEntry := range tree.Entries {
   687→		if bucketEntry.Mode != filemode.Dir {
   688→			continue
   689→		}
   690→		// Bucket should be 2 hex chars
   691→		if len(bucketEntry.Name) != 2 {
   692→			continue
   693→		}
   694→
   695→		bucketTree, treeErr := s.repo.TreeObject(bucketEntry.Hash)
   696→		if treeErr != nil {
   697→			continue
   698→		}
   699→
   700→		// Each entry in the bucket is the remaining part of the checkpoint ID
   701→		for _, checkpointEntry := range bucketTree.Entries {
   702→			if checkpointEntry.Mode != filemode.Dir {
   703→				continue
   704→			}
   705→
   706→			checkpointTree, cpTreeErr := s.repo.TreeObject(checkpointEntry.Hash)
   707→			if cpTreeErr != nil {
   708→				continue
   709→			}
   710→
   711→			// Reconstruct checkpoint ID: <bucket><remaining>
   712→			checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
   713→			checkpointID, cpIDErr := id.NewCheckpointID(checkpointIDStr)
   714→			if cpIDErr != nil {
   715→				// Skip invalid checkpoint IDs (shouldn't happen with our own data)
   716→				continue
   717→			}
   718→
   719→			info := CommittedInfo{
   720→				CheckpointID: checkpointID,
   721→			}
   722→
   723→			// Get details from metadata file
   724→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   725→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
   726→					var metadata CommittedMetadata
   727→					if err := json.Unmarshal([]byte(content), &metadata); err == nil {
   728→						info.SessionID = metadata.SessionID
   729→						info.CreatedAt = metadata.CreatedAt
   730→						info.CheckpointsCount = metadata.CheckpointsCount
   731→						info.FilesTouched = metadata.FilesTouched
   732→						info.Agent = metadata.Agent
   733→						info.IsTask = metadata.IsTask
   734→						info.ToolUseID = metadata.ToolUseID
   735→						info.SessionCount = metadata.SessionCount
   736→						info.SessionIDs = metadata.SessionIDs
   737→					}
   738→				}
   739→			}
   740→
   741→			checkpoints = append(checkpoints, info)
   742→		}
   743→	}
   744→
   745→	// Sort by time (most recent first)
   746→	sort.Slice(checkpoints, func(i, j int) bool {
   747→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
   748→	})
   749→
   750→	return checkpoints, nil
   751→}
   752→
   753→// GetTranscript retrieves the transcript for a specific checkpoint ID.
   754→func (s *GitStore) GetTranscript(ctx context.Context, checkpointID id.CheckpointID) ([]byte, error) {
   755→	result, err := s.ReadCommitted(ctx, checkpointID)
   756→	if err != nil {
   757→		return nil, err
   758→	}
   759→	if result == nil {
   760→		return nil, fmt.Errorf("checkpoint not found: %s", checkpointID)
   761→	}
   762→	if len(result.Transcript) == 0 {
   763→		return nil, fmt.Errorf("no transcript found for checkpoint: %s", checkpointID)
   764→	}
   765→	return result.Transcript, nil
   766→}
   767→
   768→// GetSessionLog retrieves the session transcript and session ID for a checkpoint.
   769→// This is the primary method for looking up session logs by checkpoint ID.
   770→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
   771→// Returns ErrNoTranscript if the checkpoint exists but has no transcript.
   772→func (s *GitStore) GetSessionLog(cpID id.CheckpointID) ([]byte, string, error) {
   773→	result, err := s.ReadCommitted(context.Background(), cpID)
   774→	if err != nil {
   775→		return nil, "", fmt.Errorf("failed to read checkpoint: %w", err)
   776→	}
   777→	if result == nil {
   778→		return nil, "", ErrCheckpointNotFound
   779→	}
   780→	if len(result.Transcript) == 0 {
   781→		return nil, "", ErrNoTranscript
   782→	}
   783→	return result.Transcript, result.Metadata.SessionID, nil
   784→}
   785→
   786→// LookupSessionLog is a convenience function that opens the repository and retrieves
   787→// a session log by checkpoint ID. This is the primary entry point for callers that
   788→// don't already have a GitStore instance.
   789→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
   790→// Returns ErrNoTranscript if the checkpoint exists but has no transcript.
   791→func LookupSessionLog(cpID id.CheckpointID) ([]byte, string, error) {
   792→	repo, err := git.PlainOpenWithOptions(".", &git.PlainOpenOptions{DetectDotGit: true})
   793→	if err != nil {
   794→		return nil, "", fmt.Errorf("failed to open git repository: %w", err)
   795→	}
   796→	store := NewGitStore(repo)
   797→	return store.GetSessionLog(cpID)
   798→}
   799→
   800→// UpdateSummary updates the summary field in an existing checkpoint's metadata.
   801→// Returns ErrCheckpointNotFound if the checkpoint doesn't exist.
   802→func (s *GitStore) UpdateSummary(ctx context.Context, checkpointID id.CheckpointID, summary *Summary) error {
   803→	_ = ctx // Reserved for future use
   804→
   805→	// Ensure sessions branch exists
   806→	if err := s.ensureSessionsBranch(); err != nil {
   807→		return fmt.Errorf("failed to ensure sessions branch: %w", err)
   808→	}
   809→
   810→	// Get current branch tip and flatten tree
   811→	ref, entries, err := s.getSessionsBranchEntries()
   812→	if err != nil {
   813→		return err
   814→	}
   815→
   816→	// Read existing metadata
   817→	basePath := checkpointID.Path() + "/"
   818→	metadataPath := basePath + paths.MetadataFileName
   819→	entry, exists := entries[metadataPath]
   820→	if !exists {
   821→		return ErrCheckpointNotFound
   822→	}
   823→
   824→	// Read and parse existing metadata
   825→	existingMetadata, err := s.readMetadataFromBlob(entry.Hash)
   826→	if err != nil {
   827→		return fmt.Errorf("failed to read existing metadata: %w", err)
   828→	}
   829→
   830→	// Update the summary
   831→	existingMetadata.Summary = summary
   832→
   833→	// Write updated metadata
   834→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(existingMetadata, "", "  ")
   835→	if err != nil {
   836→		return fmt.Errorf("failed to marshal metadata: %w", err)
   837→	}
   838→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
   839→	if err != nil {
   840→		return fmt.Errorf("failed to create metadata blob: %w", err)
   841→	}
   842→	entries[metadataPath] = object.TreeEntry{
   843→		Name: metadataPath,
   844→		Mode: filemode.Regular,
   845→		Hash: metadataHash,
   846→	}
   847→
   848→	// Build and commit
   849→	newTreeHash, err := BuildTreeFromEntries(s.repo, entries)
   850→	if err != nil {
   851→		return err
   852→	}
   853→
   854→	authorName, authorEmail := getGitAuthorFromRepo(s.repo)
   855→	commitMsg := fmt.Sprintf("Update summary for checkpoint %s (session: %s)", checkpointID, existingMetadata.SessionID)
   856→	newCommitHash, err := s.createCommit(newTreeHash, ref.Hash(), commitMsg, authorName, authorEmail)
   857→	if err != nil {
   858→		return err
   859→	}
   860→
   861→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   862→	newRef := plumbing.NewHashReference(refName, newCommitHash)
   863→	if err := s.repo.Storer.SetReference(newRef); err != nil {
   864→		return fmt.Errorf("failed to set branch reference: %w", err)
   865→	}
   866→
   867→	return nil
   868→}
   869→
   870→// ensureSessionsBranch ensures the entire/sessions branch exists.
   871→func (s *GitStore) ensureSessionsBranch() error {
   872→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   873→	_, err := s.repo.Reference(refName, true)
   874→	if err == nil {
   875→		return nil // Branch exists
   876→	}
   877→
   878→	// Create orphan branch with empty tree
   879→	emptyTreeHash, err := BuildTreeFromEntries(s.repo, make(map[string]object.TreeEntry))
   880→	if err != nil {
   881→		return err
   882→	}
   883→
   884→	authorName, authorEmail := getGitAuthorFromRepo(s.repo)
   885→	commitHash, err := s.createCommit(emptyTreeHash, plumbing.ZeroHash, "Initialize sessions branch", authorName, authorEmail)
   886→	if err != nil {
   887→		return err
   888→	}
   889→
   890→	newRef := plumbing.NewHashReference(refName, commitHash)
   891→	if err := s.repo.Storer.SetReference(newRef); err != nil {
   892→		return fmt.Errorf("failed to set branch reference: %w", err)
   893→	}
   894→	return nil
   895→}
   896→
   897→// getSessionsBranchTree returns the tree object for the entire/sessions branch.
   898→func (s *GitStore) getSessionsBranchTree() (*object.Tree, error) {
   899→	refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
   900→	ref, err := s.repo.Reference(refName, true)
   901→	if err != nil {
   902→		return nil, fmt.Errorf("sessions branch not found: %w", err)
   903→	}
   904→
   905→	commit, err := s.repo.CommitObject(ref.Hash())
   906→	if err != nil {
   907→		return nil, fmt.Errorf("failed to get commit object: %w", err)
   908→	}
   909→
   910→	tree, err := commit.Tree()
   911→	if err != nil {
   912→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
   913→	}
   914→
   915→	return tree, nil
   916→}
   917→
   918→// CreateBlobFromContent creates a blob object from in-memory content.
   919→// Exported for use by strategy package (session_test.go)
   920→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
   921→	obj := repo.Storer.NewEncodedObject()
   922→	obj.SetType(plumbing.BlobObject)
   923→	obj.SetSize(int64(len(content)))
   924→
   925→	writer, err := obj.Writer()
   926→	if err != nil {
   927→		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
   928→	}
   929→
   930→	_, err = writer.Write(content)
   931→	if err != nil {
   932→		_ = writer.Close()
   933→		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
   934→	}
   935→	if err := writer.Close(); err != nil {
   936→		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
   937→	}
   938→
   939→	hash, err := repo.Storer.SetEncodedObject(obj)
   940→	if err != nil {
   941→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
   942→	}
   943→	return hash, nil
   944→}
   945→
   946→// copyMetadataDir copies all files from a directory to the checkpoint path.
   947→// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
   948→func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
   949→	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
   950→		if err != nil {
   951→			return err
   952→		}
   953→		if info.IsDir() {
   954→			return nil
   955→		}
   956→
   957→		// Skip symlinks to prevent reading files outside the metadata directory.
   958→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
   959→		// then be captured in the checkpoint and stored in git history.
   960→		if info.Mode()&os.ModeSymlink != 0 {
   961→			return nil
   962→		}
   963→
   964→		// Get relative path within metadata dir
   965→		relPath, err := filepath.Rel(metadataDir, path)
   966→		if err != nil {
   967→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
   968→		}
   969→
   970→		// Prevent path traversal via symlinks pointing outside the metadata dir
   971→		if strings.HasPrefix(relPath, "..") {
   972→			return fmt.Errorf("path traversal detected: %s", relPath)
   973→		}
   974→
   975→		// Create blob from file
   976→		blobHash, mode, err := createBlobFromFile(s.repo, path)
   977→		if err != nil {
   978→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
   979→		}
   980→
   981→		// Store at checkpoint path
   982→		fullPath := basePath + relPath
   983→		entries[fullPath] = object.TreeEntry{
   984→			Name: fullPath,
   985→			Mode: mode,
   986→			Hash: blobHash,
   987→		}
   988→
   989→		return nil
   990→	})
   991→	if err != nil {
   992→		return fmt.Errorf("failed to walk metadata directory: %w", err)
   993→	}
   994→	return nil
   995→}
   996→
   997→// getGitAuthorFromRepo retrieves the git user.name and user.email from the repository config.
   998→func getGitAuthorFromRepo(repo *git.Repository) (name, email string) {
   999→	// Get repository config (includes local settings)
  1000→	cfg, err := repo.Config()
  1001→	if err == nil {
  1002→		name = cfg.User.Name
  1003→		email = cfg.User.Email
  1004→	}
  1005→
  1006→	// Provide sensible defaults if git user is not configured
  1007→	if name == "" {
  1008→		name = "Unknown"
  1009→	}
  1010→	if email == "" {
  1011→		email = "unknown@local"
  1012→	}
  1013→
  1014→	return name, email
  1015→}
  1016→
  1017→// readTranscriptFromTree reads a transcript from a git tree, handling both chunked and non-chunked formats.
  1018→// It checks for chunk files first (.001, .002, etc.), then falls back to the base file.
  1019→// The agentType is used for reassembling chunks in the correct format.
  1020→func readTranscriptFromTree(tree *object.Tree, agentType agent.AgentType) ([]byte, error) {
  1021→	// Collect all transcript-related files
  1022→	var chunkFiles []string
  1023→	var hasBaseFile bool
  1024→
  1025→	for _, entry := range tree.Entries {
  1026→		if entry.Name == paths.TranscriptFileName || entry.Name == paths.TranscriptFileNameLegacy {
  1027→			hasBaseFile = true
  1028→		}
  1029→		// Check for chunk files (full.jsonl.001, full.jsonl.002, etc.)
  1030→		if strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
  1031→			idx := agent.ParseChunkIndex(entry.Name, paths.TranscriptFileName)
  1032→			if idx > 0 {
  1033→				chunkFiles = append(chunkFiles, entry.Name)
  1034→			}
  1035→		}
  1036→	}
  1037→
  1038→	// If we have chunk files, read and reassemble them
  1039→	if len(chunkFiles) > 0 {
  1040→		// Sort chunk files by index
  1041→		chunkFiles = agent.SortChunkFiles(chunkFiles, paths.TranscriptFileName)
  1042→
  1043→		// Check if base file should be included as chunk 0.
  1044→		// NOTE: This assumes the chunking convention where the unsuffixed file
  1045→		// (full.jsonl) is chunk 0, and numbered files (.001, .002) are chunks 1+.
  1046→		if hasBaseFile {
  1047→			chunkFiles = append([]string{paths.TranscriptFileName}, chunkFiles...)
  1048→		}
  1049→
  1050→		var chunks [][]byte
  1051→		for _, chunkFile := range chunkFiles {
  1052→			file, err := tree.File(chunkFile)
  1053→			if err != nil {
  1054→				logging.Warn(context.Background(), "failed to read transcript chunk file from tree",
  1055→					slog.String("chunk_file", chunkFile),
  1056→					slog.String("error", err.Error()),
  1057→				)
  1058→				continue
  1059→			}
  1060→			content, err := file.Contents()
  1061→			if err != nil {
  1062→				logging.Warn(context.Background(), "failed to read transcript chunk contents",
  1063→					slog.String("chunk_file", chunkFile),
  1064→					slog.String("error", err.Error()),
  1065→				)
  1066→				continue
  1067→			}
  1068→			chunks = append(chunks, []byte(content))
  1069→		}
  1070→
  1071→		if len(chunks) > 0 {
  1072→			result, err := agent.ReassembleTranscript(chunks, agentType)
  1073→			if err != nil {
  1074→				return nil, fmt.Errorf("failed to reassemble transcript: %w", err)
  1075→			}
  1076→			return result, nil
  1077→		}
  1078→	}
  1079→
  1080→	// Fall back to reading base file (non-chunked or backwards compatibility)
  1081→	if file, err := tree.File(paths.TranscriptFileName); err == nil {
  1082→		if content, err := file.Contents(); err == nil {
  1083→			return []byte(content), nil
  1084→		}
  1085→	}
  1086→
  1087→	// Try legacy filename
  1088→	if file, err := tree.File(paths.TranscriptFileNameLegacy); err == nil {
  1089→		if content, err := file.Contents(); err == nil {
  1090→			return []byte(content), nil
  1091→		}
  1092→	}
  1093→
  1094→	return nil, nil
  1095→}
  1096→

