   351→// TestWriteTemporary_Deduplication verifies that WriteTemporary skips creating
   352→// a new commit when the tree hash matches the previous checkpoint.
   353→func TestWriteTemporary_Deduplication(t *testing.T) {
   354→	tempDir := t.TempDir()
   355→
   356→	// Initialize a git repository with an initial commit
   357→	repo, err := git.PlainInit(tempDir, false)
   358→	if err != nil {
   359→		t.Fatalf("failed to init git repo: %v", err)
   360→	}
   361→
   362→	// Create worktree and make initial commit
   363→	worktree, err := repo.Worktree()
   364→	if err != nil {
   365→		t.Fatalf("failed to get worktree: %v", err)
   366→	}
   367→
   368→	readmeFile := filepath.Join(tempDir, "README.md")
   369→	if err := os.WriteFile(readmeFile, []byte("# Test"), 0o644); err != nil {
   370→		t.Fatalf("failed to write README: %v", err)
   371→	}
   372→	if _, err := worktree.Add("README.md"); err != nil {
   373→		t.Fatalf("failed to add README: %v", err)
   374→	}
   375→	initialCommit, err := worktree.Commit("Initial commit", &git.CommitOptions{
   376→		Author: &object.Signature{Name: "Test", Email: "test@test.com"},
   377→	})
   378→	if err != nil {
   379→		t.Fatalf("failed to commit: %v", err)
   380→	}
   381→
   382→	// Change to temp dir so paths.RepoRoot() works correctly
   383→	t.Chdir(tempDir)
   384→
   385→	// Create a test file that will be included in checkpoints
   386→	testFile := filepath.Join(tempDir, "test.go")
   387→	if err := os.WriteFile(testFile, []byte("package main\n"), 0o644); err != nil {
   388→		t.Fatalf("failed to write test file: %v", err)
   389→	}
   390→
   391→	// Create metadata directory
   392→	metadataDir := filepath.Join(tempDir, ".entire", "metadata", "test-session")
   393→	if err := os.MkdirAll(metadataDir, 0o755); err != nil {
   394→		t.Fatalf("failed to create metadata dir: %v", err)
   395→	}
   396→	if err := os.WriteFile(filepath.Join(metadataDir, "full.jsonl"), []byte(`{"test": true}`), 0o644); err != nil {
   397→		t.Fatalf("failed to write transcript: %v", err)
   398→	}
   399→
   400→	// Create checkpoint store
   401→	store := NewGitStore(repo)
   402→
   403→	// First checkpoint should be created
   404→	baseCommit := initialCommit.String()
   405→	result1, err := store.WriteTemporary(context.Background(), WriteTemporaryOptions{
   406→		SessionID:         "test-session",
   407→		BaseCommit:        baseCommit,
   408→		ModifiedFiles:     []string{"test.go"},
   409→		MetadataDir:       ".entire/metadata/test-session",
   410→		MetadataDirAbs:    metadataDir,
   411→		CommitMessage:     "Checkpoint 1",
   412→		AuthorName:        "Test",
   413→		AuthorEmail:       "test@test.com",
   414→		IsFirstCheckpoint: true,
   415→	})
   416→	if err != nil {
   417→		t.Fatalf("WriteTemporary() first call error = %v", err)
   418→	}
   419→	if result1.Skipped {
   420→		t.Error("first checkpoint should not be skipped")
   421→	}
   422→	if result1.CommitHash == plumbing.ZeroHash {
   423→		t.Error("first checkpoint should have a commit hash")
   424→	}
   425→
   426→	// Second checkpoint with identical content should be skipped
   427→	result2, err := store.WriteTemporary(context.Background(), WriteTemporaryOptions{
   428→		SessionID:         "test-session",
   429→		BaseCommit:        baseCommit,
   430→		ModifiedFiles:     []string{"test.go"},
   431→		MetadataDir:       ".entire/metadata/test-session",
   432→		MetadataDirAbs:    metadataDir,
   433→		CommitMessage:     "Checkpoint 2",
   434→		AuthorName:        "Test",
   435→		AuthorEmail:       "test@test.com",
   436→		IsFirstCheckpoint: false,
   437→	})
   438→	if err != nil {
   439→		t.Fatalf("WriteTemporary() second call error = %v", err)
   440→	}
   441→	if !result2.Skipped {
   442→		t.Error("second checkpoint with identical content should be skipped")
   443→	}
   444→	if result2.CommitHash != result1.CommitHash {
   445→		t.Errorf("skipped checkpoint should return previous commit hash, got %s, want %s",
   446→			result2.CommitHash, result1.CommitHash)
   447→	}
   448→
   449→	// Modify the file and create another checkpoint - should NOT be skipped
   450→	if err := os.WriteFile(testFile, []byte("package main\n\nfunc main() {}\n"), 0o644); err != nil {
   451→		t.Fatalf("failed to modify test file: %v", err)
   452→	}
   453→
   454→	result3, err := store.WriteTemporary(context.Background(), WriteTemporaryOptions{
   455→		SessionID:         "test-session",
   456→		BaseCommit:        baseCommit,
   457→		ModifiedFiles:     []string{"test.go"},
   458→		MetadataDir:       ".entire/metadata/test-session",
   459→		MetadataDirAbs:    metadataDir,
   460→		CommitMessage:     "Checkpoint 3",
   461→		AuthorName:        "Test",
   462→		AuthorEmail:       "test@test.com",
   463→		IsFirstCheckpoint: false,
   464→	})
   465→	if err != nil {
   466→		t.Fatalf("WriteTemporary() third call error = %v", err)
   467→	}
   468→	if result3.Skipped {
   469→		t.Error("third checkpoint with modified content should NOT be skipped")
   470→	}
   471→	if result3.CommitHash == result1.CommitHash {
   472→		t.Error("third checkpoint should have a different commit hash than first")
   473→	}
   474→}
