   508→// verifyBranchInMetadata reads and verifies the branch field in metadata.json.
   509→func verifyBranchInMetadata(t *testing.T, repo *git.Repository, checkpointID id.CheckpointID, expectedBranch string, shouldOmit bool) {
   510→	t.Helper()
   511→
   512→	metadataRef, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
   513→	if err != nil {
   514→		t.Fatalf("failed to get metadata branch reference: %v", err)
   515→	}
   516→
   517→	commit, err := repo.CommitObject(metadataRef.Hash())
   518→	if err != nil {
   519→		t.Fatalf("failed to get commit object: %v", err)
   520→	}
   521→
   522→	tree, err := commit.Tree()
   523→	if err != nil {
   524→		t.Fatalf("failed to get tree: %v", err)
   525→	}
   526→
   527→	shardedPath := checkpointID.Path()
   528→	metadataPath := shardedPath + "/" + paths.MetadataFileName
   529→	metadataFile, err := tree.File(metadataPath)
   530→	if err != nil {
   531→		t.Fatalf("failed to find metadata.json at %s: %v", metadataPath, err)
   532→	}
   533→
   534→	content, err := metadataFile.Contents()
   535→	if err != nil {
   536→		t.Fatalf("failed to read metadata.json: %v", err)
   537→	}
   538→
   539→	var metadata CommittedMetadata
   540→	if err := json.Unmarshal([]byte(content), &metadata); err != nil {
   541→		t.Fatalf("failed to parse metadata.json: %v", err)
   542→	}
   543→
   544→	if metadata.Branch != expectedBranch {
   545→		t.Errorf("metadata.Branch = %q, want %q", metadata.Branch, expectedBranch)
   546→	}
   547→
   548→	if shouldOmit && strings.Contains(content, `"branch"`) {
   549→		t.Errorf("metadata.json should not contain 'branch' field when empty (omitempty), got:\n%s", content)
   550→	}
   551→}
