   553→// TestArchiveExistingSession_ChunkedTranscript verifies that when archiving
   554→// a session with chunked transcripts, all chunk files are moved to the archive folder.
   555→func TestArchiveExistingSession_ChunkedTranscript(t *testing.T) {
