   558→
   559→	basePath := "a1/b2c3d4e5f6/"
   560→
   561→	// Simulate existing checkpoint with chunked transcript
   562→	// Chunk 0 is the base file (full.jsonl), chunks 1+ have suffixes (.001, .002)
   563→	entries := map[string]object.TreeEntry{
   564→		basePath + paths.MetadataFileName:            {Name: basePath + paths.MetadataFileName, Hash: plumbing.NewHash("aaa")},
   565→		basePath + paths.TranscriptFileName:          {Name: basePath + paths.TranscriptFileName, Hash: plumbing.NewHash("bbb")},          // chunk 0
   566→		basePath + paths.TranscriptFileName + ".001": {Name: basePath + paths.TranscriptFileName + ".001", Hash: plumbing.NewHash("ccc")}, // chunk 1
   567→		basePath + paths.TranscriptFileName + ".002": {Name: basePath + paths.TranscriptFileName + ".002", Hash: plumbing.NewHash("ddd")}, // chunk 2
   568→		basePath + paths.PromptFileName:              {Name: basePath + paths.PromptFileName, Hash: plumbing.NewHash("eee")},
   569→		basePath + paths.ContextFileName:             {Name: basePath + paths.ContextFileName, Hash: plumbing.NewHash("fff")},
   570→		basePath + paths.ContentHashFileName:         {Name: basePath + paths.ContentHashFileName, Hash: plumbing.NewHash("ggg")},
   571→	}
   572→
   573→	existingMetadata := &CommittedMetadata{
   574→		SessionCount: 1,
   575→	}
   576→
   577→	// Archive the existing session
   578→	store.archiveExistingSession(basePath, existingMetadata, entries)
   579→
   580→	archivePath := basePath + "1/"
   581→
   582→	// Verify standard files were archived
   583→	if _, ok := entries[archivePath+paths.MetadataFileName]; !ok {
   584→		t.Error("metadata.json should be archived to 1/")
   585→	}
   586→	if _, ok := entries[archivePath+paths.TranscriptFileName]; !ok {
   587→		t.Error("full.jsonl (chunk 0) should be archived to 1/")
   588→	}
   589→	if _, ok := entries[archivePath+paths.PromptFileName]; !ok {
   590→		t.Error("prompt.txt should be archived to 1/")
   591→	}
   592→
   593→	// Verify chunk files were archived
   594→	if _, ok := entries[archivePath+paths.TranscriptFileName+".001"]; !ok {
   595→		t.Error("full.jsonl.001 (chunk 1) should be archived to 1/")
   596→	}
   597→	if _, ok := entries[archivePath+paths.TranscriptFileName+".002"]; !ok {
   598→		t.Error("full.jsonl.002 (chunk 2) should be archived to 1/")
   599→	}
   600→
   601→	// Verify original locations are cleared
   602→	if _, ok := entries[basePath+paths.TranscriptFileName]; ok {
   603→		t.Error("original full.jsonl should be removed from base path")
   604→	}
   605→	if _, ok := entries[basePath+paths.TranscriptFileName+".001"]; ok {
   606→		t.Error("original full.jsonl.001 should be removed from base path")
   607→	}
   608→	if _, ok := entries[basePath+paths.TranscriptFileName+".002"]; ok {
   609→		t.Error("original full.jsonl.002 should be removed from base path")
   610→	}
   611→}
