   613→// TestWriteCommitted_BranchField verifies that the Branch field is correctly
   614→// captured in metadata.json when on a branch, and is empty when in detached HEAD.
   615→func TestWriteCommitted_BranchField(t *testing.T) {
   616→	t.Run("on branch", func(t *testing.T) {
   617→		repo, commitHash := setupBranchTestRepo(t)
   618→
   619→		// Create a feature branch and switch to it
   620→		branchName := "feature/test-branch"
   621→		branchRef := plumbing.NewBranchReferenceName(branchName)
   622→		ref := plumbing.NewHashReference(branchRef, commitHash)
   623→		if err := repo.Storer.SetReference(ref); err != nil {
   624→			t.Fatalf("failed to create branch: %v", err)
   625→		}
   626→
   627→		worktree, err := repo.Worktree()
   628→		if err != nil {
   629→			t.Fatalf("failed to get worktree: %v", err)
   630→		}
   631→		if err := worktree.Checkout(&git.CheckoutOptions{Branch: branchRef}); err != nil {
   632→			t.Fatalf("failed to checkout branch: %v", err)
   633→		}
   634→
   635→		// Get current branch name
   636→		var currentBranch string
   637→		head, err := repo.Head()
   638→		if err == nil && head.Name().IsBranch() {
   639→			currentBranch = head.Name().Short()
   640→		}
   641→
   642→		// Write a committed checkpoint with branch information
   643→		checkpointID := id.MustCheckpointID("a1b2c3d4e5f6")
   644→		store := NewGitStore(repo)
   645→		err = store.WriteCommitted(context.Background(), WriteCommittedOptions{
   646→			CheckpointID: checkpointID,
   647→			SessionID:    "test-session-123",
   648→			Strategy:     "manual-commit",
   649→			Branch:       currentBranch,
   650→			Transcript:   []byte("test transcript content"),
   651→			AuthorName:   "Test Author",
   652→			AuthorEmail:  "test@example.com",
   653→		})
   654→		if err != nil {
   655→			t.Fatalf("WriteCommitted() error = %v", err)
   656→		}
   657→
   658→		verifyBranchInMetadata(t, repo, checkpointID, branchName, false)
   659→	})
   660→
   661→	t.Run("detached HEAD", func(t *testing.T) {
