// writeSessionToSubdirectory writes a single session's files to a numbered subdirectory.
// Returns the relative file paths within the checkpoint for the sessions map.
func (s *GitStore) writeSessionToSubdirectory(opts WriteCommittedOptions, sessionPath string, entries map[string]object.TreeEntry) (SessionFilePaths, error) {
	filePaths := SessionFilePaths{}

	// Extract session index from path for relative paths in sessions map
	// sessionPath is like "a1/b2c3d4e5f6/0/" - we want "0/"
	parts := strings.Split(strings.TrimSuffix(sessionPath, "/"), "/")
	sessionDir := parts[len(parts)-1] + "/"

	// Write transcript
	if err := s.writeTranscript(opts, sessionPath, entries); err != nil {
		return filePaths, err
	}
	filePaths.Transcript = sessionDir + paths.TranscriptFileName
	filePaths.ContentHash = sessionDir + paths.ContentHashFileName

