		if len(existingAgents) == 0 && existingMetadata.Agent != "" {
			// Backwards compat: old metadata only had Agent
			existingAgents = []agent.AgentType{existingMetadata.Agent}
		}
		metadata.Agents = mergeAgents(existingAgents, opts.Agent)
