	if err != nil {
		return fmt.Errorf("failed to read existing metadata: %w", err)
	}

	// Update the summary
	existingMetadata.Summary = summary

	// Write updated metadata
	metadataJSON, err := jsonutil.MarshalIndentWithNewline(existingMetadata, "", "  ")
	if err != nil {
