}

// writeCheckpointSummary writes the root-level CheckpointSummary with aggregated statistics.
func (s *GitStore) writeCheckpointSummary(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, existingSummary *CheckpointSummary, sessionFilePaths SessionFilePaths) error {
	summary := CheckpointSummary{
		CheckpointID:     opts.CheckpointID,
		Strategy:         opts.Strategy,
		CreatedAt:        time.Now().UTC(),
		Branch:           opts.Branch,
		CheckpointsCount: opts.CheckpointsCount,
		FilesTouched:     opts.FilesTouched,
		SessionCount:     1,
		SessionIDs:       []string{opts.SessionID},
		Sessions:         map[string]SessionFilePaths{opts.SessionID: sessionFilePaths},
		TokenUsage:       opts.TokenUsage,
	}

	// Set Agents array (always include current agent)
	if opts.Agent != "" {
		summary.Agents = []agent.AgentType{opts.Agent}
	}

	// Aggregate with existing summary if present
	if existingSummary != nil {
		summary.SessionCount = existingSummary.SessionCount + 1
		summary.SessionIDs = existingSummary.SessionIDs
		summary.SessionIDs = append(summary.SessionIDs, opts.SessionID)
		summary.CheckpointsCount = existingSummary.CheckpointsCount + opts.CheckpointsCount
		summary.FilesTouched = mergeFilesTouched(existingSummary.FilesTouched, opts.FilesTouched)
		summary.Agents = mergeAgents(existingSummary.Agents, opts.Agent)
		summary.TokenUsage = aggregateTokenUsage(existingSummary.TokenUsage, opts.TokenUsage)

//	├── 1/                    # Second session
//	└── 2/                    # Third session...
//
//nolint:revive // Named CheckpointSummary to avoid conflict with existing Summary struct
type CheckpointSummary struct {
	CheckpointID     id.CheckpointID             `json:"checkpoint_id"`
	Strategy         string                      `json:"strategy"`
	CreatedAt        time.Time                   `json:"created_at"`
	Branch           string                      `json:"branch,omitempty"`
	CheckpointsCount int                         `json:"checkpoints_count"`
	FilesTouched     []string                    `json:"files_touched"`
	Agents           []agent.AgentType           `json:"agents,omitempty"`
	SessionCount     int                         `json:"session_count"`
	SessionIDs       []string                    `json:"session_ids"`
	Sessions         map[string]SessionFilePaths `json:"sessions"`
	TokenUsage       *agent.TokenUsage           `json:"token_usage,omitempty"`
}

