				content, _ := summaryFile.Contents()
				var summary checkpoint.CheckpointSummary
				if json.Unmarshal([]byte(content), &summary) == nil && len(summary.Sessions) > 0 {
					// Use session ID to find transcript path
					if sessionPaths, ok := summary.Sessions[metadata.SessionID]; ok && sessionPaths.Transcript != "" {
						transcriptPath = checkpointPath + "/" + sessionPaths.Transcript
					}
				}
			}
		}

		// Fall back to old format if sessions map not available
		if transcriptPath == "" {
			transcriptPath = checkpointPath + "/" + paths.TranscriptFileName
