   896→// GitCommitWithShadowHooks stages and commits files, simulating the prepare-commit-msg and post-commit hooks.
   897→// This is used for testing manual-commit strategy which needs:
   898→// - prepare-commit-msg hook: adds the Entire-Checkpoint trailer
   899→// - post-commit hook: condenses session data if trailer is present
   900→func (env *TestEnv) GitCommitWithShadowHooks(message string, files ...string) {
   901→	env.T.Helper()
   902→
   903→	// Stage files using go-git
   904→	for _, file := range files {
   905→		env.GitAdd(file)
   906→	}
   907→
   908→	// Create a temp file for the commit message (prepare-commit-msg hook modifies this)
   909→	msgFile := filepath.Join(env.RepoDir, ".git", "COMMIT_EDITMSG")
   910→	if err := os.WriteFile(msgFile, []byte(message), 0o644); err != nil {
   911→		env.T.Fatalf("failed to write commit message file: %v", err)
   912→	}
   913→
   914→	// Run prepare-commit-msg hook using the shared binary
   915→	prepCmd := exec.Command(getTestBinary(), "hooks", "git", "prepare-commit-msg", msgFile)
   916→	prepCmd.Dir = env.RepoDir
   917→	if output, err := prepCmd.CombinedOutput(); err != nil {
   918→		env.T.Logf("prepare-commit-msg output: %s", output)
   919→		// Don't fail - hook may silently succeed
   920→	}
   921→
   922→	// Read the modified message
   923→	modifiedMsg, err := os.ReadFile(msgFile)
   924→	if err != nil {
   925→		env.T.Fatalf("failed to read modified commit message: %v", err)
   926→	}
   927→
   928→	// Create the commit using go-git with the modified message
   929→	repo, err := git.PlainOpen(env.RepoDir)
   930→	if err != nil {
   931→		env.T.Fatalf("failed to open git repo: %v", err)
   932→	}
   933→
   934→	worktree, err := repo.Worktree()
   935→	if err != nil {
   936→		env.T.Fatalf("failed to get worktree: %v", err)
   937→	}
   938→
   939→	_, err = worktree.Commit(string(modifiedMsg), &git.CommitOptions{
   940→		Author: &object.Signature{
   941→			Name:  "Test User",
   942→			Email: "test@example.com",
   943→			When:  time.Now(),
   944→		},
   945→	})
   946→	if err != nil {
   947→		env.T.Fatalf("failed to commit: %v", err)
   948→	}
   949→
   950→	// Run post-commit hook using the shared binary
   951→	// This triggers condensation if the commit has an Entire-Checkpoint trailer
   952→	postCmd := exec.Command(getTestBinary(), "hooks", "git", "post-commit")
   953→	postCmd.Dir = env.RepoDir
   954→	if output, err := postCmd.CombinedOutput(); err != nil {
   955→		env.T.Logf("post-commit output: %s", output)
   956→		// Don't fail - hook may silently succeed
   957→	}
   958→}
