   960→// GitCommitWithTrailerRemoved stages and commits files, simulating what happens when
   961→// a user removes the Entire-Checkpoint trailer during commit message editing.
   962→// This tests the opt-out behavior where removing the trailer skips condensation.
   963→func (env *TestEnv) GitCommitWithTrailerRemoved(message string, files ...string) {
   964→	env.T.Helper()
   965→
   966→	// Stage files using go-git
   967→	for _, file := range files {
   968→		env.GitAdd(file)
   969→	}
   970→
   971→	// Create a temp file for the commit message (prepare-commit-msg hook modifies this)
   972→	msgFile := filepath.Join(env.RepoDir, ".git", "COMMIT_EDITMSG")
   973→	if err := os.WriteFile(msgFile, []byte(message), 0o644); err != nil {
   974→		env.T.Fatalf("failed to write commit message file: %v", err)
   975→	}
   976→
   977→	// Run prepare-commit-msg hook using the shared binary
   978→	prepCmd := exec.Command(getTestBinary(), "hooks", "git", "prepare-commit-msg", msgFile)
   979→	prepCmd.Dir = env.RepoDir
   980→	if output, err := prepCmd.CombinedOutput(); err != nil {
   981→		env.T.Logf("prepare-commit-msg output: %s", output)
   982→	}
   983→
   984→	// Read the modified message (with trailer added by hook)
   985→	modifiedMsg, err := os.ReadFile(msgFile)
   986→	if err != nil {
   987→		env.T.Fatalf("failed to read modified commit message: %v", err)
   988→	}
   989→
   990→	// REMOVE the Entire-Checkpoint trailer (simulating user editing the message)
   991→	lines := strings.Split(string(modifiedMsg), "\n")
   992→	var cleanedLines []string
   993→	for _, line := range lines {
   994→		// Skip the trailer and the comments about it
   995→		if strings.HasPrefix(line, "Entire-Checkpoint:") {
   996→			continue
   997→		}
   998→		if strings.Contains(line, "Remove the Entire-Checkpoint trailer") {
   999→			continue
  1000→		}
  1001→		if strings.Contains(line, "trailer will be added to your next commit") {
  1002→			continue
  1003→		}
  1004→		cleanedLines = append(cleanedLines, line)
  1005→	}
  1006→	cleanedMsg := strings.TrimRight(strings.Join(cleanedLines, "\n"), "\n") + "\n"
  1007→
  1008→	// Create the commit using go-git with the cleaned message (no trailer)
  1009→	repo, err := git.PlainOpen(env.RepoDir)
  1010→	if err != nil {
  1011→		env.T.Fatalf("failed to open git repo: %v", err)
  1012→	}
  1013→
  1014→	worktree, err := repo.Worktree()
  1015→	if err != nil {
  1016→		env.T.Fatalf("failed to get worktree: %v", err)
  1017→	}
  1018→
  1019→	_, err = worktree.Commit(cleanedMsg, &git.CommitOptions{
  1020→		Author: &object.Signature{
  1021→			Name:  "Test User",
  1022→			Email: "test@example.com",
  1023→			When:  time.Now(),
  1024→		},
  1025→	})
  1026→	if err != nil {
  1027→		env.T.Fatalf("failed to commit: %v", err)
  1028→	}
  1029→
  1030→	// Run post-commit hook - since trailer was removed, no condensation should happen
  1031→	postCmd := exec.Command(getTestBinary(), "hooks", "git", "post-commit")
  1032→	postCmd.Dir = env.RepoDir
  1033→	if output, err := postCmd.CombinedOutput(); err != nil {
  1034→		env.T.Logf("post-commit output: %s", output)
  1035→	}
  1036→}
