  1155→// GetLatestCheckpointIDFromHistory walks backwards from HEAD on the active branch
  1156→// and returns the checkpoint ID from the first commit that has an Entire-Checkpoint trailer.
  1157→// This verifies that condensation actually happened (commit has trailer) without relying
  1158→// on timestamp-based matching.
  1159→func (env *TestEnv) GetLatestCheckpointIDFromHistory() string {
  1160→	env.T.Helper()
  1161→
  1162→	repo, err := git.PlainOpen(env.RepoDir)
  1163→	if err != nil {
  1164→		env.T.Fatalf("failed to open git repo: %v", err)
  1165→	}
  1166→
  1167→	head, err := repo.Head()
  1168→	if err != nil {
  1169→		env.T.Fatalf("failed to get HEAD: %v", err)
  1170→	}
  1171→
  1172→	commitIter, err := repo.Log(&git.LogOptions{From: head.Hash()})
  1173→	if err != nil {
  1174→		env.T.Fatalf("failed to iterate commits: %v", err)
  1175→	}
  1176→
  1177→	var checkpointID string
  1178→	//nolint:errcheck // ForEach callback handles errors
  1179→	commitIter.ForEach(func(c *object.Commit) error {
  1180→		if cpID, found := trailers.ParseCheckpoint(c.Message); found {
  1181→			checkpointID = cpID.String()
  1182→			return errors.New("stop iteration") // Found it, stop
  1183→		}
  1184→		return nil
  1185→	})
  1186→
  1187→	if checkpointID == "" {
  1188→		env.T.Fatalf("no commit with Entire-Checkpoint trailer found in history")
  1189→	}
  1190→
  1191→	return checkpointID
  1192→}
