  1218→func findModuleRoot() string {
  1219→	// Start from this source file's location and walk up to find go.mod
  1220→	_, thisFile, _, ok := runtime.Caller(0)
  1221→	if !ok {
  1222→		panic("failed to get current file path via runtime.Caller")
  1223→	}
  1224→	dir := filepath.Dir(thisFile)
  1225→
  1226→	for {
  1227→		if _, err := os.Stat(filepath.Join(dir, "go.mod")); err == nil {
  1228→			return dir
  1229→		}
  1230→		parent := filepath.Dir(dir)
  1231→		if parent == dir {
  1232→			panic("could not find go.mod starting from " + thisFile)
  1233→		}
  1234→		dir = parent
  1235→	}
  1236→}
