    14→// TestGeminiConcurrentSessionWarning_BlocksFirstPrompt verifies that when a user starts
    15→// a new Gemini session while another session has uncommitted changes (checkpoints),
    16→// the first prompt is blocked with a Gemini-format JSON response (decision: block).
    17→func TestGeminiConcurrentSessionWarning_BlocksFirstPrompt(t *testing.T) {
    18→	env := NewTestEnv(t)
    19→	defer env.Cleanup()
    20→
    21→	env.InitRepo()
    22→	env.WriteFile("README.md", "# Test")
    23→	env.GitAdd("README.md")
    24→	env.GitCommit("Initial commit")
    25→	env.GitCheckoutNewBranch("feature/test")
    26→	env.InitEntireWithAgent(strategy.StrategyNameManualCommit, "gemini")
    27→
    28→	// Start session A and create a checkpoint
    29→	sessionA := env.NewGeminiSession()
    30→	if err := env.SimulateGeminiBeforeAgent(sessionA.ID); err != nil {
    31→		t.Fatalf("SimulateGeminiBeforeAgent (sessionA) failed: %v", err)
    32→	}
    33→
    34→	env.WriteFile("file.txt", "content from session A")
    35→	sessionA.CreateGeminiTranscript("Add file", []FileChange{{Path: "file.txt", Content: "content from session A"}})
    36→	if err := env.SimulateGeminiSessionEnd(sessionA.ID, sessionA.TranscriptPath); err != nil {
    37→		t.Fatalf("SimulateGeminiSessionEnd (sessionA) failed: %v", err)
    38→	}
    39→
    40→	// Verify session A has checkpoints
    41→	stateA, err := env.GetSessionState(sessionA.ID)
    42→	if err != nil {
    43→		t.Fatalf("GetSessionState (sessionA) failed: %v", err)
    44→	}
    45→	if stateA == nil {
    46→		t.Fatal("Session A state should exist after SessionEnd hook")
    47→	}
    48→	if stateA.CheckpointCount == 0 {
    49→		t.Fatal("Session A should have at least 1 checkpoint")
    50→	}
    51→	t.Logf("Session A has %d checkpoint(s)", stateA.CheckpointCount)
    52→
    53→	// Start session B - first prompt should be blocked
    54→	sessionB := env.NewGeminiSession()
    55→	output := env.SimulateGeminiBeforeAgentWithOutput(sessionB.ID)
    56→
    57→	// Gemini blocking exits with code 0 (JSON parsed) and decision "block"
    58→	if output.Err != nil {
    59→		t.Fatalf("Hook should exit with code 0 for blocking, got error: %v", output.Err)
    60→	}
    61→
    62→	// Parse the JSON response (Gemini format)
    63→	var response struct {
    64→		Decision string `json:"decision"`
    65→		Reason   string `json:"reason"`
    66→	}
    67→	if err := json.Unmarshal(output.Stdout, &response); err != nil {
    68→		t.Fatalf("Failed to parse JSON response: %v\nStdout: %s", err, output.Stdout)
    69→	}
    70→
    71→	// Verify decision is block
    72→	if response.Decision != "block" {
    73→		t.Errorf("Expected decision:block in JSON response, got: %s", response.Decision)
    74→	}
    75→
    76→	// Verify reason contains expected message
    77→	expectedMessage := "Another session is active"
    78→	if !strings.Contains(response.Reason, expectedMessage) {
    79→		t.Errorf("Reason should contain %q, got: %s", expectedMessage, response.Reason)
    80→	}
    81→
    82→	// Verify the resume command mentions gemini --resume
    83→	expectedResumeCmd := "gemini --resume"
    84→	if !strings.Contains(response.Reason, expectedResumeCmd) {
    85→		t.Errorf("Reason should contain %q, got: %s", expectedResumeCmd, response.Reason)
    86→	}
    87→
    88→	t.Logf("Received expected blocking response: %s", output.Stdout)
    89→}
