   135→// TestGeminiConcurrentSessionWarning_SubsequentPromptsSucceed verifies that after the
   136→// warning is shown, subsequent prompts in the same session proceed normally.
   137→func TestGeminiConcurrentSessionWarning_SubsequentPromptsSucceed(t *testing.T) {
   138→	env := NewTestEnv(t)
   139→	defer env.Cleanup()
   140→
   141→	env.InitRepo()
   142→	env.WriteFile("README.md", "# Test")
   143→	env.GitAdd("README.md")
   144→	env.GitCommit("Initial commit")
   145→	env.GitCheckoutNewBranch("feature/test")
   146→	env.InitEntireWithAgent(strategy.StrategyNameManualCommit, "gemini")
   147→
   148→	// Start session A and create a checkpoint
   149→	sessionA := env.NewGeminiSession()
   150→	if err := env.SimulateGeminiBeforeAgent(sessionA.ID); err != nil {
   151→		t.Fatalf("SimulateGeminiBeforeAgent (sessionA) failed: %v", err)
   152→	}
   153→
   154→	env.WriteFile("file.txt", "content")
   155→	sessionA.CreateGeminiTranscript("Add file", []FileChange{{Path: "file.txt", Content: "content"}})
   156→	if err := env.SimulateGeminiAfterAgent(sessionA.ID, sessionA.TranscriptPath); err != nil {
   157→		t.Fatalf("SimulateGeminiAfterAgent (sessionA) failed: %v", err)
   158→	}
   159→
   160→	// Start session B - first prompt is blocked (exits with code 0, decision: block)
   161→	sessionB := env.NewGeminiSession()
   162→	output1 := env.SimulateGeminiBeforeAgentWithOutput(sessionB.ID)
   163→
   164→	// Verify first prompt was blocked (exit code 0 with decision: block)
   165→	if output1.Err != nil {
   166→		t.Fatalf("First prompt should exit with code 0, got error: %v", output1.Err)
   167→	}
   168→
   169→	var response1 struct {
   170→		Decision string `json:"decision"`
   171→	}
   172→	if err := json.Unmarshal(output1.Stdout, &response1); err != nil {
   173→		t.Fatalf("Failed to parse first response: %v", err)
   174→	}
   175→	if response1.Decision != "block" {
   176→		t.Fatalf("First prompt should have decision:block, got: %s", response1.Decision)
   177→	}
   178→	t.Log("First prompt correctly blocked")
   179→
   180→	// Second prompt in session B should PROCEED normally (both sessions capture checkpoints)
   181→	// The warning was shown on first prompt, but subsequent prompts continue to capture state
   182→	output2 := env.SimulateGeminiBeforeAgentWithOutput(sessionB.ID)
   183→
   184→	// The hook should succeed
   185→	if output2.Err != nil {
   186→		t.Errorf("Second prompt should succeed, got error: %v", output2.Err)
   187→	}
   188→
   189→	// The hook should process normally (capture state) - no blocking response
   190→	if len(output2.Stdout) > 0 {
