   192→		var blockResponse struct {
   193→			Decision string `json:"decision"`
   194→		}
   195→		if json.Unmarshal(output2.Stdout, &blockResponse) == nil && blockResponse.Decision == "block" {
   196→			t.Errorf("Second prompt should not be blocked after warning was shown, got: %s", output2.Stdout)
   197→		}
   198→	}
   199→
   200→	// Warning flag should remain set (for tracking)
   201→	stateB, _ := env.GetSessionState(sessionB.ID)
   202→	if stateB == nil {
   203→		t.Fatal("Session B state should exist")
   204→	}
   205→	if !stateB.ConcurrentWarningShown {
   206→		t.Error("ConcurrentWarningShown should remain true after second prompt")
   207→	}
