   595→// TestGeminiConcurrentSessions_BothCondensedOnCommit verifies that when two sessions have
   596→// interleaved checkpoints, committing preserves both sessions' logs on entire/sessions.
   597→func TestGeminiConcurrentSessions_BothCondensedOnCommit(t *testing.T) {
   598→	env := NewTestEnv(t)
   599→	defer env.Cleanup()
   600→
   601→	env.InitRepo()
   602→	env.WriteFile("README.md", "# Test")
   603→	env.GitAdd("README.md")
   604→	env.GitCommit("Initial commit")
   605→	env.GitCheckoutNewBranch("feature/test")
   606→	env.InitEntireWithAgent(strategy.StrategyNameManualCommit, "gemini")
   607→
   608→	// Session A: create checkpoint
   609→	sessionA := env.NewGeminiSession()
   610→	if err := env.SimulateGeminiBeforeAgent(sessionA.ID); err != nil {
   611→		t.Fatalf("SimulateGeminiBeforeAgent (sessionA) failed: %v", err)
   612→	}
   613→
   614→	env.WriteFile("fileA.txt", "content from session A")
   615→	sessionA.CreateGeminiTranscript("Add file A", []FileChange{{Path: "fileA.txt", Content: "content from session A"}})
   616→	if err := env.SimulateGeminiAfterAgent(sessionA.ID, sessionA.TranscriptPath); err != nil {
   617→		t.Fatalf("SimulateGeminiAfterAgent (sessionA) failed: %v", err)
   618→	}
   619→
   620→	// Session B: acknowledge warning and create checkpoint
   621→	sessionB := env.NewGeminiSession()
   622→	// First prompt is blocked with warning
   623→	_ = env.SimulateGeminiBeforeAgentWithOutput(sessionB.ID)
   624→
   625→	// Second prompt proceeds (after warning was shown)
   626→	if err := env.SimulateGeminiBeforeAgent(sessionB.ID); err != nil {
   627→		t.Fatalf("SimulateGeminiBeforeAgent (sessionB second prompt) failed: %v", err)
   628→	}
   629→
   630→	env.WriteFile("fileB.txt", "content from session B")
   631→	sessionB.CreateGeminiTranscript("Add file B", []FileChange{{Path: "fileB.txt", Content: "content from session B"}})
   632→	if err := env.SimulateGeminiAfterAgent(sessionB.ID, sessionB.TranscriptPath); err != nil {
   633→		t.Fatalf("SimulateGeminiAfterAgent (sessionB) failed: %v", err)
   634→	}
   635→
   636→	// Verify both sessions have checkpoints
   637→	stateA, _ := env.GetSessionState(sessionA.ID)
   638→	stateB, _ := env.GetSessionState(sessionB.ID)
   639→	if stateA == nil || stateA.CheckpointCount == 0 {
   640→		t.Fatal("Session A should have checkpoints")
   641→	}
   642→	if stateB == nil || stateB.CheckpointCount == 0 {
   643→		t.Fatal("Session B should have checkpoints")
   644→	}
   645→	t.Logf("Session A: %d checkpoints, Session B: %d checkpoints", stateA.CheckpointCount, stateB.CheckpointCount)
   646→
   647→	// Commit with hooks - this should condense both sessions
   648→	env.GitCommitWithShadowHooks("Add files from both sessions", "fileA.txt", "fileB.txt")
   649→
   650→	// Get the checkpoint ID from entire/sessions
   651→	checkpointID := env.GetLatestCheckpointID()
   652→	if checkpointID == "" {
   653→		t.Fatal("Failed to get checkpoint ID from entire/sessions branch")
   654→	}
   655→	t.Logf("Checkpoint ID: %s", checkpointID)
   656→
   657→	// Build the sharded path
   658→	shardedPath := checkpointID[:2] + "/" + checkpointID[2:]
   659→
   660→	// Verify metadata.json exists and has multi-session info
   661→	metadataContent, found := env.ReadFileFromBranch("entire/sessions", shardedPath+"/metadata.json")
   662→	if !found {
   663→		t.Fatal("metadata.json should exist on entire/sessions branch")
   664→	}
   665→
   666→	var metadata struct {
   667→		SessionCount int      `json:"session_count"`
   668→		SessionIDs   []string `json:"session_ids"`
   669→		SessionID    string   `json:"session_id"`
   670→	}
   671→	if err := json.Unmarshal([]byte(metadataContent), &metadata); err != nil {
   672→		t.Fatalf("Failed to parse metadata.json: %v", err)
   673→	}
   674→
   675→	t.Logf("Metadata: session_count=%d, session_ids=%v, session_id=%s",
   676→		metadata.SessionCount, metadata.SessionIDs, metadata.SessionID)
   677→
   678→	// Verify multi-session fields
   679→	if metadata.SessionCount != 2 {
   680→		t.Errorf("Expected session_count=2, got %d", metadata.SessionCount)
   681→	}
   682→	if len(metadata.SessionIDs) != 2 {
   683→		t.Errorf("Expected 2 session_ids, got %d", len(metadata.SessionIDs))
   684→	}
   685→
   686→	// Verify archived session exists in subfolder "1/"
   687→	archivedMetadata, found := env.ReadFileFromBranch("entire/sessions", shardedPath+"/1/metadata.json")
   688→	if !found {
   689→		t.Error("Archived session metadata should exist at 1/metadata.json")
   690→	} else {
   691→		t.Logf("Archived session metadata found: %s", archivedMetadata[:min(100, len(archivedMetadata))])
   692→	}
   693→
   694→	// Verify transcript exists for current session (at root)
   695→	if !env.FileExistsInBranch("entire/sessions", shardedPath+"/full.jsonl") {
   696→		t.Error("Current session transcript should exist at root (full.jsonl)")
   697→	}
   698→
   699→	// Verify transcript exists for archived session
   700→	if !env.FileExistsInBranch("entire/sessions", shardedPath+"/1/full.jsonl") {
   701→		t.Error("Archived session transcript should exist at 1/full.jsonl")
   702→	}
   703→
   704→	t.Log("Both sessions successfully condensed with proper archiving")
   705→}
