    99→// CondenseSession condenses a session's shadow branch to permanent storage.
   100→// checkpointID is the 12-hex-char value from the Entire-Checkpoint trailer.
   101→// Metadata is stored at sharded path: <checkpoint_id[:2]>/<checkpoint_id[2:]>/
   102→// Uses checkpoint.GitStore.WriteCommitted for the git operations.
   103→func (s *ManualCommitStrategy) CondenseSession(repo *git.Repository, checkpointID id.CheckpointID, state *SessionState) (*CondenseResult, error) {
   104→	// Get shadow branch
   105→	shadowBranchName := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
   106→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
   107→	ref, err := repo.Reference(refName, true)
   108→	if err != nil {
   109→		return nil, fmt.Errorf("shadow branch not found: %w", err)
   110→	}
   111→
   112→	// Extract session data from the shadow branch
   113→	// Use tracked files from session state instead of collecting all files from tree
   114→	// Pass agent type to handle different transcript formats (JSONL for Claude, JSON for Gemini)
   115→	sessionData, err := s.extractSessionData(repo, ref.Hash(), state.SessionID, state.FilesTouched, state.AgentType)
   116→	if err != nil {
   117→		return nil, fmt.Errorf("failed to extract session data: %w", err)
   118→	}
   119→
   120→	// Get checkpoint store
   121→	store, err := s.getCheckpointStore()
   122→	if err != nil {
   123→		return nil, fmt.Errorf("failed to get checkpoint store: %w", err)
   124→	}
   125→
   126→	// Get author info
   127→	authorName, authorEmail := GetGitAuthorFromRepo(repo)
   128→	attribution := calculateSessionAttributions(repo, ref, sessionData, state)
   129→	// Get current branch name
   130→	branchName := GetCurrentBranchName(repo)
   131→
   132→	// Write checkpoint metadata using the checkpoint store
   133→	if err := store.WriteCommitted(context.Background(), cpkg.WriteCommittedOptions{
   134→		CheckpointID:                checkpointID,
   135→		SessionID:                   state.SessionID,
   136→		Strategy:                    StrategyNameManualCommit,
   137→		Branch:                      branchName,
   138→		Transcript:                  sessionData.Transcript,
   139→		Prompts:                     sessionData.Prompts,
   140→		Context:                     sessionData.Context,
   141→		FilesTouched:                sessionData.FilesTouched,
   142→		CheckpointsCount:            state.CheckpointCount,
   143→		EphemeralBranch:             shadowBranchName,
   144→		AuthorName:                  authorName,
   145→		AuthorEmail:                 authorEmail,
   146→		Agent:                       state.AgentType,
   147→		TranscriptIdentifierAtStart: state.TranscriptIdentifierAtStart,
   148→		TranscriptLinesAtStart:      state.TranscriptLinesAtStart,
   149→		TokenUsage:                  sessionData.TokenUsage,
   150→		InitialAttribution:          attribution,
   151→	}); err != nil {
   152→		return nil, fmt.Errorf("failed to write checkpoint metadata: %w", err)
   153→	}
   154→
   155→	return &CondenseResult{
   156→		CheckpointID:         checkpointID,
   157→		SessionID:            state.SessionID,
   158→		CheckpointsCount:     state.CheckpointCount,
   159→		FilesTouched:         sessionData.FilesTouched,
   160→		TotalTranscriptLines: sessionData.FullTranscriptLines,
   161→	}, nil
   162→}
