   164→func calculateSessionAttributions(repo *git.Repository, shadowRef *plumbing.Reference, sessionData *ExtractedSessionData, state *SessionState) *cpkg.InitialAttribution {
   165→	// Calculate initial attribution using accumulated prompt attribution data.
   166→	// This uses user edits captured at each prompt start (before agent works),
   167→	// plus any user edits after the final checkpoint (shadow → head).
   168→	logCtx := logging.WithComponent(context.Background(), "attribution")
   169→	var attribution *cpkg.InitialAttribution
   170→	headRef, headErr := repo.Head()
   171→	if headErr != nil {
   172→		logging.Debug(logCtx, "attribution skipped: failed to get HEAD",
   173→			slog.String("error", headErr.Error()))
   174→	} else {
   175→		headCommit, commitErr := repo.CommitObject(headRef.Hash())
   176→		if commitErr != nil {
   177→			logging.Debug(logCtx, "attribution skipped: failed to get HEAD commit",
   178→				slog.String("error", commitErr.Error()))
   179→		} else {
   180→			headTree, treeErr := headCommit.Tree()
   181→			if treeErr != nil {
   182→				logging.Debug(logCtx, "attribution skipped: failed to get HEAD tree",
   183→					slog.String("error", treeErr.Error()))
   184→			} else {
   185→				// Get shadow branch tree (checkpoint tree - what the agent wrote)
   186→				shadowCommit, shadowErr := repo.CommitObject(shadowRef.Hash())
   187→				if shadowErr != nil {
   188→					logging.Debug(logCtx, "attribution skipped: failed to get shadow commit",
   189→						slog.String("error", shadowErr.Error()),
   190→						slog.String("shadow_ref", shadowRef.Hash().String()))
   191→				} else {
   192→					shadowTree, shadowTreeErr := shadowCommit.Tree()
   193→					if shadowTreeErr != nil {
   194→						logging.Debug(logCtx, "attribution skipped: failed to get shadow tree",
   195→							slog.String("error", shadowTreeErr.Error()))
   196→					} else {
   197→						// Get base tree (state before session started)
   198→						var baseTree *object.Tree
   199→						if baseCommit, baseErr := repo.CommitObject(plumbing.NewHash(state.BaseCommit)); baseErr == nil {
   200→							if tree, baseTErr := baseCommit.Tree(); baseTErr == nil {
   201→								baseTree = tree
   202→							} else {
   203→								logging.Debug(logCtx, "attribution: base tree unavailable",
   204→									slog.String("error", baseTErr.Error()))
   205→							}
   206→						} else {
   207→							logging.Debug(logCtx, "attribution: base commit unavailable",
   208→								slog.String("error", baseErr.Error()),
   209→								slog.String("base_commit", state.BaseCommit))
   210→						}
   211→
   212→						// Log accumulated prompt attributions for debugging
   213→						var totalUserAdded, totalUserRemoved int
   214→						for i, pa := range state.PromptAttributions {
   215→							totalUserAdded += pa.UserLinesAdded
   216→							totalUserRemoved += pa.UserLinesRemoved
   217→							logging.Debug(logCtx, "prompt attribution data",
   218→								slog.Int("checkpoint", pa.CheckpointNumber),
   219→								slog.Int("user_added", pa.UserLinesAdded),
   220→								slog.Int("user_removed", pa.UserLinesRemoved),
   221→								slog.Int("agent_added", pa.AgentLinesAdded),
   222→								slog.Int("agent_removed", pa.AgentLinesRemoved),
   223→								slog.Int("index", i))
   224→						}
   225→
   226→						attribution = CalculateAttributionWithAccumulated(
   227→							baseTree,
   228→							shadowTree,
   229→							headTree,
   230→							sessionData.FilesTouched,
   231→							state.PromptAttributions,
   232→						)
   233→
   234→						if attribution != nil {
   235→							logging.Info(logCtx, "attribution calculated",
   236→								slog.Int("agent_lines", attribution.AgentLines),
   237→								slog.Int("human_added", attribution.HumanAdded),
   238→								slog.Int("human_modified", attribution.HumanModified),
   239→								slog.Int("human_removed", attribution.HumanRemoved),
   240→								slog.Int("total_committed", attribution.TotalCommitted),
   241→								slog.Float64("agent_percentage", attribution.AgentPercentage),
   242→								slog.Int("accumulated_user_added", totalUserAdded),
   243→								slog.Int("accumulated_user_removed", totalUserRemoved),
   244→								slog.Int("files_touched", len(sessionData.FilesTouched)))
   245→						}
   246→					}
   247→				}
   248→			}
   249→		}
   250→	}
   251→	return attribution
   252→}
