   254→// extractSessionData extracts session data from the shadow branch.
   255→// filesTouched is the list of files tracked during the session (from SessionState.FilesTouched).
   256→// agentType identifies the agent (e.g., "Gemini CLI", "Claude Code") to determine transcript format.
   257→func (s *ManualCommitStrategy) extractSessionData(repo *git.Repository, shadowRef plumbing.Hash, sessionID string, filesTouched []string, agentType agent.AgentType) (*ExtractedSessionData, error) {
   258→	commit, err := repo.CommitObject(shadowRef)
   259→	if err != nil {
   260→		return nil, fmt.Errorf("failed to get commit object: %w", err)
   261→	}
   262→
   263→	tree, err := commit.Tree()
   264→	if err != nil {
   265→		return nil, fmt.Errorf("failed to get commit tree: %w", err)
   266→	}
   267→
   268→	data := &ExtractedSessionData{}
   269→	// sessionID is already an "entire session ID" (with date prefix)
   270→	metadataDir := paths.SessionMetadataDirFromEntireID(sessionID)
   271→
   272→	// Extract transcript
   273→	// TODO: remove paths.TranscriptFileNameLegacy usage ?
   274→	var fullTranscript string
   275→	if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileName); fileErr == nil {
   276→		if content, contentErr := file.Contents(); contentErr == nil {
   277→			fullTranscript = content
   278→		}
   279→	} else if file, fileErr := tree.File(metadataDir + "/" + paths.TranscriptFileNameLegacy); fileErr == nil {
   280→		if content, contentErr := file.Contents(); contentErr == nil {
   281→			fullTranscript = content
   282→		}
   283→	}
   284→
   285→	// Process transcript based on agent type
   286→	if fullTranscript != "" {
   287→		// Check if this is a Gemini CLI transcript (JSON format, not JSONL)
   288→		isGeminiFormat := agentType == agent.AgentTypeGemini || isGeminiJSONTranscript(fullTranscript)
   289→
   290→		if isGeminiFormat {
   291→			// Gemini uses JSON format with a "messages" array
   292→			data.Transcript = []byte(fullTranscript)
   293→			data.FullTranscriptLines = 1 // JSON is a single "line"
   294→			data.Prompts = extractUserPromptsFromGeminiJSON(fullTranscript)
   295→			data.Context = generateContextFromPrompts(data.Prompts)
   296→		} else {
   297→			// Claude Code and others use JSONL format (one JSON object per line)
   298→			allLines := strings.Split(fullTranscript, "\n")
   299→
   300→			// Trim trailing empty lines (from final \n in JSONL)
   301→			for len(allLines) > 0 && strings.TrimSpace(allLines[len(allLines)-1]) == "" {
   302→				allLines = allLines[:len(allLines)-1]
   303→			}
   304→
   305→			data.FullTranscriptLines = len(allLines)
   306→
   307→			// Always store the full transcript for complete session history
   308→			data.Transcript = []byte(strings.Join(allLines, "\n"))
   309→
   310→			// Extract prompts from the full transcript
   311→			data.Prompts = extractUserPromptsFromLines(allLines)
   312→
   313→			// Generate context from prompts
   314→			data.Context = generateContextFromPrompts(data.Prompts)
   315→		}
   316→	}
   317→
   318→	// Use tracked files from session state (not all files in tree)
   319→	data.FilesTouched = filesTouched
   320→
   321→	// Calculate token usage from the extracted transcript portion
   322→	// TODO: Missing Gemini token usage
   323→	if len(data.Transcript) > 0 {
   324→		// TODO: Calculate token usage per transcript slice (only checkpoint related)
   325→		transcriptLines, err := claudecode.ParseTranscript(data.Transcript)
   326→		if err == nil && len(transcriptLines) > 0 {
   327→			data.TokenUsage = claudecode.CalculateTokenUsage(transcriptLines)
   328→		}
   329→	}
   330→
   331→	return data, nil
   332→}
