   346→// writeCheckpointSummary writes the root-level CheckpointSummary with aggregated statistics.
   347→func (s *GitStore) writeCheckpointSummary(opts WriteCommittedOptions, basePath string, entries map[string]object.TreeEntry, existingSummary *CheckpointSummary, sessionFilePaths SessionFilePaths) error {
   348→	summary := CheckpointSummary{
   349→		CheckpointID:     opts.CheckpointID,
   350→		Strategy:         opts.Strategy,
   351→		CreatedAt:        time.Now().UTC(),
   352→		Branch:           opts.Branch,
   353→		CheckpointsCount: opts.CheckpointsCount,
   354→		FilesTouched:     opts.FilesTouched,
   355→		SessionCount:     1,
   356→		SessionIDs:       []string{opts.SessionID},
   357→		Sessions:         map[string]SessionFilePaths{opts.SessionID: sessionFilePaths},
   358→		TokenUsage:       opts.TokenUsage,
   359→	}
   360→
   361→	// Set Agents array (always include current agent)
   362→	if opts.Agent != "" {
   363→		summary.Agents = []agent.AgentType{opts.Agent}
   364→	}
   365→
   366→	// Aggregate with existing summary if present
   367→	if existingSummary != nil {
   368→		summary.SessionCount = existingSummary.SessionCount + 1
   369→		summary.SessionIDs = existingSummary.SessionIDs
   370→		summary.SessionIDs = append(summary.SessionIDs, opts.SessionID)
   371→		summary.CheckpointsCount = existingSummary.CheckpointsCount + opts.CheckpointsCount
   372→		summary.FilesTouched = mergeFilesTouched(existingSummary.FilesTouched, opts.FilesTouched)
   373→		summary.Agents = mergeAgents(existingSummary.Agents, opts.Agent)
   374→		summary.TokenUsage = aggregateTokenUsage(existingSummary.TokenUsage, opts.TokenUsage)
   375→
   376→		// Preserve existing sessions map and add new session
   377→		summary.Sessions = make(map[string]SessionFilePaths)
   378→		for k, v := range existingSummary.Sessions {
   379→			summary.Sessions[k] = v
   380→		}
   381→		summary.Sessions[opts.SessionID] = sessionFilePaths
   382→	}
   383→
   384→	metadataJSON, err := jsonutil.MarshalIndentWithNewline(summary, "", "  ")
   385→	if err != nil {
   386→		return fmt.Errorf("failed to marshal checkpoint summary: %w", err)
   387→	}
   388→	metadataHash, err := CreateBlobFromContent(s.repo, metadataJSON)
   389→	if err != nil {
   390→		return err
   391→	}
   392→	entries[basePath+paths.MetadataFileName] = object.TreeEntry{
   393→		Name: basePath + paths.MetadataFileName,
   394→		Mode: filemode.Regular,
   395→		Hash: metadataHash,
   396→	}
   397→	return nil
   398→}
