   426→// aggregateTokenUsage sums two TokenUsage structs.
   427→// Returns nil if both inputs are nil.
   428→func aggregateTokenUsage(a, b *agent.TokenUsage) *agent.TokenUsage {
   429→	if a == nil && b == nil {
   430→		return nil
   431→	}
   432→	result := &agent.TokenUsage{}
   433→	if a != nil {
   434→		result.InputTokens = a.InputTokens
   435→		result.CacheCreationTokens = a.CacheCreationTokens
   436→		result.CacheReadTokens = a.CacheReadTokens
   437→		result.OutputTokens = a.OutputTokens
   438→		result.APICallCount = a.APICallCount
   439→	}
   440→	if b != nil {
   441→		result.InputTokens += b.InputTokens
   442→		result.CacheCreationTokens += b.CacheCreationTokens
   443→		result.CacheReadTokens += b.CacheReadTokens
   444→		result.OutputTokens += b.OutputTokens
   445→		result.APICallCount += b.APICallCount
   446→	}
   447→	return result
   448→}
