   500→// mergeFilesTouched combines two file lists, removing duplicates.
   501→func mergeFilesTouched(existing, additional []string) []string {
   502→	seen := make(map[string]bool)
   503→	var result []string
   504→
   505→	for _, f := range existing {
   506→		if !seen[f] {
   507→			seen[f] = true
   508→			result = append(result, f)
   509→		}
   510→	}
   511→	for _, f := range additional {
   512→		if !seen[f] {
   513→			seen[f] = true
   514→			result = append(result, f)
   515→		}
   516→	}
   517→
   518→	sort.Strings(result)
   519→	return result
   520→}
   521→
   522→// mergeAgents combines existing agents with a new agent, removing duplicates.
   523→// Preserves order (existing agents first, then new agent if not already present).
   524→func mergeAgents(existing []agent.AgentType, newAgent agent.AgentType) []agent.AgentType {
   525→	if newAgent == "" {
   526→		return existing
   527→	}
   528→
   529→	seen := make(map[agent.AgentType]bool)
   530→	var result []agent.AgentType
   531→
   532→	for _, a := range existing {
   533→		if !seen[a] {
   534→			seen[a] = true
   535→			result = append(result, a)
   536→		}
   537→	}
   538→
   539→	if !seen[newAgent] {
   540→		result = append(result, newAgent)
   541→	}
   542→
   543→	return result
   544→}
