   551→// archiveExistingSession moves existing session files to a numbered subfolder.
   552→// The subfolder number is based on the current session count (so first archived session goes to "1/").
   553→func (s *GitStore) archiveExistingSession(basePath string, existingMetadata *CommittedMetadata, entries map[string]object.TreeEntry) {
   554→	// Determine archive folder number
   555→	sessionCount := existingMetadata.SessionCount
   556→	if sessionCount == 0 {
   557→		sessionCount = 1 // backwards compat
   558→	}
   559→	archivePath := fmt.Sprintf("%s%d/", basePath, sessionCount)
   560→
   561→	// Files to archive (standard checkpoint files at basePath, excluding tasks/ subfolder)
   562→	filesToArchive := []string{
   563→		paths.MetadataFileName,
   564→		paths.TranscriptFileName,
   565→		paths.PromptFileName,
   566→		paths.ContextFileName,
   567→		paths.ContentHashFileName,
   568→	}
   569→
   570→	// Also include transcript chunk files (full.jsonl.001, full.jsonl.002, etc.)
   571→	chunkPrefix := basePath + paths.TranscriptFileName + "."
   572→	for srcPath := range entries {
   573→		if strings.HasPrefix(srcPath, chunkPrefix) {
   574→			chunkSuffix := strings.TrimPrefix(srcPath, basePath+paths.TranscriptFileName)
   575→			if idx := agent.ParseChunkIndex(paths.TranscriptFileName+chunkSuffix, paths.TranscriptFileName); idx > 0 {
   576→				filesToArchive = append(filesToArchive, paths.TranscriptFileName+chunkSuffix)
   577→			}
   578→		}
   579→	}
   580→
   581→	// Move each file to archive folder
   582→	for _, filename := range filesToArchive {
   583→		srcPath := basePath + filename
   584→		if entry, exists := entries[srcPath]; exists {
   585→			// Add to archive location
   586→			dstPath := archivePath + filename
   587→			entries[dstPath] = object.TreeEntry{
   588→				Name: dstPath,
   589→				Mode: entry.Mode,
   590→				Hash: entry.Hash,
   591→			}
   592→			// Remove from original location (will be overwritten by new session)
   593→			delete(entries, srcPath)
   594→		}
   595→	}
   596→}
