   598→// readArchivedSessions reads transcript data from archived session subfolders (1/, 2/, etc.).
   599→// Returns sessions ordered by folder index (oldest first).
   600→func (s *GitStore) readArchivedSessions(checkpointTree *object.Tree, sessionCount int, agentType agent.AgentType) []ArchivedSession {
   601→	var archived []ArchivedSession
   602→
   603→	// Archived sessions are in numbered folders: 1/, 2/, etc.
   604→	// The most recent session is at the root level (not archived).
   605→	// Session count N means there are N-1 archived sessions.
   606→	for i := 1; i < sessionCount; i++ {
   607→		folderName := strconv.Itoa(i)
   608→
   609→		// Try to get the archived session subtree
   610→		subTree, err := checkpointTree.Tree(folderName)
   611→		if err != nil {
   612→			continue // Folder doesn't exist, skip
   613→		}
   614→
   615→		session := ArchivedSession{
   616→			FolderIndex: i,
   617→		}
   618→
   619→		// Read metadata to get session ID
   620→		if metadataFile, fileErr := subTree.File(paths.MetadataFileName); fileErr == nil {
   621→			if content, contentErr := metadataFile.Contents(); contentErr == nil {
   622→				var metadata CommittedMetadata
   623→				if jsonErr := json.Unmarshal([]byte(content), &metadata); jsonErr == nil {
   624→					session.SessionID = metadata.SessionID
   625→				}
   626→			}
   627→		}
   628→
   629→		// Read transcript (handles both chunked and non-chunked formats)
   630→		if transcript, err := readTranscriptFromTree(subTree, agentType); err == nil && transcript != nil {
   631→			session.Transcript = transcript
   632→		}
   633→
   634→		// Read prompts
   635→		if file, fileErr := subTree.File(paths.PromptFileName); fileErr == nil {
   636→			if content, contentErr := file.Contents(); contentErr == nil {
   637→				session.Prompts = content
   638→			}
   639→		}
   640→
   641→		// Only add if we got a transcript
   642→		if len(session.Transcript) > 0 {
   643→			archived = append(archived, session)
   644→		}
   645→	}
   646→
   647→	return archived
   648→}
