   650→// buildCommitMessage constructs the commit message with proper trailers.
   651→// The commit subject is always "Checkpoint: <id>" for consistency.
   652→// If CommitSubject is provided (e.g., for task checkpoints), it's included in the body.
   653→func (s *GitStore) buildCommitMessage(opts WriteCommittedOptions, taskMetadataPath string) string {
   654→	var commitMsg strings.Builder
   655→
   656→	// Subject line is always the checkpoint ID for consistent formatting
   657→	commitMsg.WriteString(fmt.Sprintf("Checkpoint: %s\n\n", opts.CheckpointID))
   658→
   659→	// Include custom description in body if provided (e.g., task checkpoint details)
   660→	if opts.CommitSubject != "" {
   661→		commitMsg.WriteString(opts.CommitSubject + "\n\n")
   662→	}
   663→	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.SessionTrailerKey, opts.SessionID))
   664→	commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.StrategyTrailerKey, opts.Strategy))
   665→	if opts.Agent != "" {
   666→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.AgentTrailerKey, opts.Agent))
   667→	}
   668→	if opts.EphemeralBranch != "" {
   669→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.EphemeralBranchTrailerKey, opts.EphemeralBranch))
   670→	}
   671→	if taskMetadataPath != "" {
   672→		commitMsg.WriteString(fmt.Sprintf("%s: %s\n", trailers.MetadataTaskTrailerKey, taskMetadataPath))
   673→	}
   674→
   675→	return commitMsg.String()
   676→}
