   696→// ReadCommitted reads a committed checkpoint by ID from the entire/sessions branch.
   697→// Returns nil, nil if the checkpoint doesn't exist.
   698→//
   699→// The new storage format uses numbered subdirectories for each session:
   700→//
   701→//	<checkpoint-id>/
   702→//	├── metadata.json      # CheckpointSummary with sessions map
   703→//	├── 0/                 # First session
   704→//	│   ├── metadata.json  # Session-specific metadata
   705→//	│   └── full.jsonl     # Transcript
   706→//	├── 1/                 # Second session
   707→//	└── ...
   708→func (s *GitStore) ReadCommitted(ctx context.Context, checkpointID id.CheckpointID) (*ReadCommittedResult, error) {
   709→	_ = ctx // Reserved for future use
   710→
   711→	tree, err := s.getSessionsBranchTree()
   712→	if err != nil {
   713→		return nil, nil //nolint:nilnil,nilerr // No sessions branch means no checkpoint exists
   714→	}
   715→
   716→	checkpointPath := checkpointID.Path()
   717→	checkpointTree, err := tree.Tree(checkpointPath)
   718→	if err != nil {
   719→		return nil, nil //nolint:nilnil,nilerr // Checkpoint directory not found
   720→	}
   721→
   722→	result := &ReadCommittedResult{}
   723→
   724→	// Read root metadata.json as CheckpointSummary
   725→	var summary CheckpointSummary
   726→	if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   727→		if content, contentErr := metadataFile.Contents(); contentErr == nil {
   728→			//nolint:errcheck,gosec // Best-effort parsing, defaults are fine
   729→			json.Unmarshal([]byte(content), &summary)
   730→		}
   731→	}
   732→
   733→	// Convert CheckpointSummary to CommittedMetadata for backwards compatibility
   734→	result.Metadata = CommittedMetadata{
   735→		CheckpointID:     summary.CheckpointID,
   736→		Strategy:         summary.Strategy,
   737→		CreatedAt:        summary.CreatedAt,
   738→		Branch:           summary.Branch,
   739→		CheckpointsCount: summary.CheckpointsCount,
   740→		FilesTouched:     summary.FilesTouched,
   741→		SessionCount:     summary.SessionCount,
   742→		SessionIDs:       summary.SessionIDs,
   743→		TokenUsage:       summary.TokenUsage,
   744→	}
   745→
   746→	// Set Agent from Agents array (first agent for backwards compat)
   747→	if len(summary.Agents) > 0 {
   748→		result.Metadata.Agent = summary.Agents[0]
   749→		result.Metadata.Agents = summary.Agents
   750→	}
   751→
   752→	// Set SessionID to latest session
   753→	if len(summary.SessionIDs) > 0 {
   754→		result.Metadata.SessionID = summary.SessionIDs[len(summary.SessionIDs)-1]
   755→	}
   756→
   757→	// Read data from the appropriate session subdirectories
   758→	if summary.SessionCount > 0 && len(summary.Sessions) > 0 {
   759→		// Find the latest session index (highest numbered directory)
   760→		latestIndex := summary.SessionCount - 1
   761→
   762→		// Read latest session data
   763→		latestDir := strconv.Itoa(latestIndex)
   764→		if latestTree, treeErr := checkpointTree.Tree(latestDir); treeErr == nil {
   765→			// Get agent type from session-specific metadata if available
   766→			agentType := result.Metadata.Agent
   767→			if sessionMetadataFile, fileErr := latestTree.File(paths.MetadataFileName); fileErr == nil {
   768→				if content, contentErr := sessionMetadataFile.Contents(); contentErr == nil {
   769→					var sessionMetadata CommittedMetadata
   770→					if jsonErr := json.Unmarshal([]byte(content), &sessionMetadata); jsonErr == nil {
   771→						agentType = sessionMetadata.Agent
   772→					}
   773→				}
   774→			}
   775→
   776→			// Read transcript
   777→			if transcript, transcriptErr := readTranscriptFromTree(latestTree, agentType); transcriptErr == nil && transcript != nil {
   778→				result.Transcript = transcript
   779→			}
   780→
   781→			// Read prompts
   782→			if file, fileErr := latestTree.File(paths.PromptFileName); fileErr == nil {
   783→				if content, contentErr := file.Contents(); contentErr == nil {
   784→					result.Prompts = content
   785→				}
   786→			}
   787→
   788→			// Read context
   789→			if file, fileErr := latestTree.File(paths.ContextFileName); fileErr == nil {
   790→				if content, contentErr := file.Contents(); contentErr == nil {
   791→					result.Context = content
   792→				}
   793→			}
   794→		}
   795→
   796→		// Read archived sessions (all except the latest)
   797→		result.ArchivedSessions = s.readArchivedSessionsFromSummary(checkpointTree, summary)
   798→	}
   799→
   800→	return result, nil
   801→}
   802→
   803→// readArchivedSessionsFromSummary reads transcript data from archived session subdirectories using the sessions map.
   804→// Returns sessions ordered by folder index (oldest first), excluding the latest session.
   805→func (s *GitStore) readArchivedSessionsFromSummary(checkpointTree *object.Tree, summary CheckpointSummary) []ArchivedSession {
   806→	var archived []ArchivedSession
   807→
   808→	// Iterate through all sessions except the latest
   809→	for i := range summary.SessionCount - 1 {
   810→		folderName := strconv.Itoa(i)
   811→
   812→		// Try to get the session subtree
   813→		subTree, err := checkpointTree.Tree(folderName)
   814→		if err != nil {
   815→			continue // Folder doesn't exist, skip
   816→		}
   817→
   818→		session := ArchivedSession{
   819→			FolderIndex: i,
   820→		}
   821→
   822→		// Get agent type from session metadata
   823→		var agentType agent.AgentType
   824→		if metadataFile, fileErr := subTree.File(paths.MetadataFileName); fileErr == nil {
   825→			if content, contentErr := metadataFile.Contents(); contentErr == nil {
   826→				var metadata CommittedMetadata
   827→				if jsonErr := json.Unmarshal([]byte(content), &metadata); jsonErr == nil {
   828→					session.SessionID = metadata.SessionID
   829→					agentType = metadata.Agent
   830→				}
   831→			}
   832→		}
   833→
   834→		// Read transcript (handles both chunked and non-chunked formats)
   835→		if transcript, err := readTranscriptFromTree(subTree, agentType); err == nil && transcript != nil {
   836→			session.Transcript = transcript
