   855→// ListCommitted lists all committed checkpoints from the entire/sessions branch.
   856→// Scans sharded paths: <id[:2]>/<id[2:]>/ directories containing metadata.json.
   857→//
   858→
   859→func (s *GitStore) ListCommitted(ctx context.Context) ([]CommittedInfo, error) {
   860→	_ = ctx // Reserved for future use
   861→
   862→	tree, err := s.getSessionsBranchTree()
   863→	if err != nil {
   864→		return []CommittedInfo{}, nil //nolint:nilerr // No sessions branch means empty list
   865→	}
   866→
   867→	var checkpoints []CommittedInfo
   868→
   869→	// Scan sharded structure: <2-char-prefix>/<remaining-id>/metadata.json
   870→	for _, bucketEntry := range tree.Entries {
   871→		if bucketEntry.Mode != filemode.Dir {
   872→			continue
   873→		}
   874→		// Bucket should be 2 hex chars
   875→		if len(bucketEntry.Name) != 2 {
   876→			continue
   877→		}
   878→
   879→		bucketTree, treeErr := s.repo.TreeObject(bucketEntry.Hash)
   880→		if treeErr != nil {
   881→			continue
   882→		}
   883→
   884→		// Each entry in the bucket is the remaining part of the checkpoint ID
   885→		for _, checkpointEntry := range bucketTree.Entries {
   886→			if checkpointEntry.Mode != filemode.Dir {
   887→				continue
   888→			}
   889→
   890→			checkpointTree, cpTreeErr := s.repo.TreeObject(checkpointEntry.Hash)
   891→			if cpTreeErr != nil {
   892→				continue
   893→			}
   894→
   895→			// Reconstruct checkpoint ID: <bucket><remaining>
   896→			checkpointIDStr := bucketEntry.Name + checkpointEntry.Name
   897→			checkpointID, cpIDErr := id.NewCheckpointID(checkpointIDStr)
   898→			if cpIDErr != nil {
   899→				// Skip invalid checkpoint IDs (shouldn't happen with our own data)
   900→				continue
   901→			}
   902→
   903→			info := CommittedInfo{
   904→				CheckpointID: checkpointID,
   905→			}
   906→
   907→			// Get details from metadata file
   908→			if metadataFile, fileErr := checkpointTree.File(paths.MetadataFileName); fileErr == nil {
   909→				if content, contentErr := metadataFile.Contents(); contentErr == nil {
   910→					var metadata CommittedMetadata
   911→					if err := json.Unmarshal([]byte(content), &metadata); err == nil {
   912→						info.SessionID = metadata.SessionID
   913→						info.CreatedAt = metadata.CreatedAt
   914→						info.CheckpointsCount = metadata.CheckpointsCount
   915→						info.FilesTouched = metadata.FilesTouched
   916→						info.Agent = metadata.Agent
   917→						info.IsTask = metadata.IsTask
   918→						info.ToolUseID = metadata.ToolUseID
   919→						info.SessionCount = metadata.SessionCount
   920→						info.SessionIDs = metadata.SessionIDs
   921→					}
   922→				}
   923→			}
   924→
   925→			checkpoints = append(checkpoints, info)
   926→		}
   927→	}
   928→
   929→	// Sort by time (most recent first)
   930→	sort.Slice(checkpoints, func(i, j int) bool {
   931→		return checkpoints[i].CreatedAt.After(checkpoints[j].CreatedAt)
   932→	})
   933→
   934→	return checkpoints, nil
   935→}
