  1115→// CreateBlobFromContent creates a blob object from in-memory content.
  1116→// Exported for use by strategy package (session_test.go)
  1117→func CreateBlobFromContent(repo *git.Repository, content []byte) (plumbing.Hash, error) {
  1118→	obj := repo.Storer.NewEncodedObject()
  1119→	obj.SetType(plumbing.BlobObject)
  1120→	obj.SetSize(int64(len(content)))
  1121→
  1122→	writer, err := obj.Writer()
  1123→	if err != nil {
  1124→		return plumbing.ZeroHash, fmt.Errorf("failed to get object writer: %w", err)
  1125→	}
  1126→
  1127→	_, err = writer.Write(content)
  1128→	if err != nil {
  1129→		_ = writer.Close()
  1130→		return plumbing.ZeroHash, fmt.Errorf("failed to write blob content: %w", err)
  1131→	}
  1132→	if err := writer.Close(); err != nil {
  1133→		return plumbing.ZeroHash, fmt.Errorf("failed to close blob writer: %w", err)
  1134→	}
  1135→
  1136→	hash, err := repo.Storer.SetEncodedObject(obj)
  1137→	if err != nil {
  1138→		return plumbing.ZeroHash, fmt.Errorf("failed to store blob object: %w", err)
  1139→	}
  1140→	return hash, nil
  1141→}
