  1143→// copyMetadataDir copies all files from a directory to the checkpoint path.
  1144→// Used to include additional metadata files like task checkpoints, subagent transcripts, etc.
  1145→func (s *GitStore) copyMetadataDir(metadataDir, basePath string, entries map[string]object.TreeEntry) error {
  1146→	err := filepath.Walk(metadataDir, func(path string, info os.FileInfo, err error) error {
  1147→		if err != nil {
  1148→			return err
  1149→		}
  1150→		if info.IsDir() {
  1151→			return nil
  1152→		}
  1153→
  1154→		// Skip symlinks to prevent reading files outside the metadata directory.
  1155→		// A symlink could point to sensitive files (e.g., /etc/passwd) which would
  1156→		// then be captured in the checkpoint and stored in git history.
  1157→		if info.Mode()&os.ModeSymlink != 0 {
  1158→			return nil
  1159→		}
  1160→
  1161→		// Get relative path within metadata dir
  1162→		relPath, err := filepath.Rel(metadataDir, path)
  1163→		if err != nil {
  1164→			return fmt.Errorf("failed to get relative path for %s: %w", path, err)
  1165→		}
  1166→
  1167→		// Prevent path traversal via symlinks pointing outside the metadata dir
  1168→		if strings.HasPrefix(relPath, "..") {
  1169→			return fmt.Errorf("path traversal detected: %s", relPath)
  1170→		}
  1171→
  1172→		// Create blob from file
  1173→		blobHash, mode, err := createBlobFromFile(s.repo, path)
  1174→		if err != nil {
  1175→			return fmt.Errorf("failed to create blob for %s: %w", path, err)
  1176→		}
  1177→
  1178→		// Store at checkpoint path
  1179→		fullPath := basePath + relPath
  1180→		entries[fullPath] = object.TreeEntry{
  1181→			Name: fullPath,
  1182→			Mode: mode,
  1183→			Hash: blobHash,
  1184→		}
  1185→
  1186→		return nil
  1187→	})
  1188→	if err != nil {
  1189→		return fmt.Errorf("failed to walk metadata directory: %w", err)
  1190→	}
  1191→	return nil
  1192→}
