  1214→// readTranscriptFromTree reads a transcript from a git tree, handling both chunked and non-chunked formats.
  1215→// It checks for chunk files first (.001, .002, etc.), then falls back to the base file.
  1216→// The agentType is used for reassembling chunks in the correct format.
  1217→func readTranscriptFromTree(tree *object.Tree, agentType agent.AgentType) ([]byte, error) {
  1218→	// Collect all transcript-related files
  1219→	var chunkFiles []string
  1220→	var hasBaseFile bool
  1221→
  1222→	for _, entry := range tree.Entries {
  1223→		if entry.Name == paths.TranscriptFileName || entry.Name == paths.TranscriptFileNameLegacy {
  1224→			hasBaseFile = true
  1225→		}
  1226→		// Check for chunk files (full.jsonl.001, full.jsonl.002, etc.)
  1227→		if strings.HasPrefix(entry.Name, paths.TranscriptFileName+".") {
  1228→			idx := agent.ParseChunkIndex(entry.Name, paths.TranscriptFileName)
  1229→			if idx > 0 {
  1230→				chunkFiles = append(chunkFiles, entry.Name)
  1231→			}
  1232→		}
  1233→	}
  1234→
  1235→	// If we have chunk files, read and reassemble them
  1236→	if len(chunkFiles) > 0 {
  1237→		// Sort chunk files by index
  1238→		chunkFiles = agent.SortChunkFiles(chunkFiles, paths.TranscriptFileName)
  1239→
  1240→		// Check if base file should be included as chunk 0.
  1241→		// NOTE: This assumes the chunking convention where the unsuffixed file
  1242→		// (full.jsonl) is chunk 0, and numbered files (.001, .002) are chunks 1+.
  1243→		if hasBaseFile {
  1244→			chunkFiles = append([]string{paths.TranscriptFileName}, chunkFiles...)
  1245→		}
  1246→
  1247→		var chunks [][]byte
  1248→		for _, chunkFile := range chunkFiles {
  1249→			file, err := tree.File(chunkFile)
  1250→			if err != nil {
  1251→				logging.Warn(context.Background(), "failed to read transcript chunk file from tree",
  1252→					slog.String("chunk_file", chunkFile),
  1253→					slog.String("error", err.Error()),
  1254→				)
  1255→				continue
  1256→			}
  1257→			content, err := file.Contents()
  1258→			if err != nil {
  1259→				logging.Warn(context.Background(), "failed to read transcript chunk contents",
  1260→					slog.String("chunk_file", chunkFile),
  1261→					slog.String("error", err.Error()),
  1262→				)
  1263→				continue
  1264→			}
  1265→			chunks = append(chunks, []byte(content))
  1266→		}
  1267→
  1268→		if len(chunks) > 0 {
  1269→			result, err := agent.ReassembleTranscript(chunks, agentType)
  1270→			if err != nil {
  1271→				return nil, fmt.Errorf("failed to reassemble transcript: %w", err)
  1272→			}
  1273→			return result, nil
  1274→		}
  1275→	}
  1276→
  1277→	// Fall back to reading base file (non-chunked or backwards compatibility)
  1278→	if file, err := tree.File(paths.TranscriptFileName); err == nil {
  1279→		if content, err := file.Contents(); err == nil {
  1280→			return []byte(content), nil
  1281→		}
  1282→	}
  1283→
  1284→	// Try legacy filename
  1285→	if file, err := tree.File(paths.TranscriptFileNameLegacy); err == nil {
  1286→		if content, err := file.Contents(); err == nil {
  1287→			return []byte(content), nil
  1288→		}
  1289→	}
  1290→
  1291→	return nil, nil
  1292→}
